TEMAS = []  # dicts: key, hub, rutas, label, nom, lead, resumen, secs, datos, nota, fuente, rel

def T_(key, hub, rutas, label, nom, lead, resumen, secs, datos, nota, fuente, rel):
    TEMAS.append(dict(key=key, hub=hub, rutas=rutas, label=label, nom=nom, lead=lead, resumen=resumen, secs=secs, datos=datos, nota=nota, fuente=fuente, rel=rel))

# ============================ CATALUNYA ============================
T_("catinst", "catalunya", ("catalunya/instituciones/", "ca/catalunya/institucions/"), ("Catalunya · Instituciones", "Catalunya · Institucions"),
 ("Las instituciones de Catalunya", "Les institucions de Catalunya"),
 ("Quién hace las leyes catalanas, quién gobierna y quién controla: la Generalitat por dentro.", "Qui fa les lleis catalanes, qui governa i qui controla: la Generalitat per dins."),
 ("La Generalitat de Catalunya es el sistema institucional con el que Catalunya se autogobierna. La forman el Parlament, que aprueba las leyes y elige al President; el President, que dirige el Govern; y el Govern, que gobierna y administra. Otras instituciones controlan su trabajo: el Síndic de Greuges, la Sindicatura de Comptes y el Consell de Garanties Estatutàries.",
  "La Generalitat de Catalunya és el sistema institucional amb què Catalunya s'autogoverna. La formen el Parlament, que aprova les lleis i elegeix el President; el President, que dirigeix el Govern; i el Govern, que governa i administra. Altres institucions en controlen la feina: el Síndic de Greuges, la Sindicatura de Comptes i el Consell de Garanties Estatutàries."),
 [S("El Parlament de Catalunya", "El Parlament de Catalunya",
    "<p>Tiene <b>135 diputados</b> elegidos cada cuatro años en cuatro circunscripciones (Barcelona 85, Girona 17, Lleida 15 y Tarragona 18). Aprueba las leyes catalanas y los presupuestos, elige al President y controla al Govern con preguntas, interpelaciones y comisiones. Tiene su sede en el antiguo arsenal de la Ciutadella, en Barcelona.</p><p>Las leyes que aprueba se publican en el <b>Diari Oficial de la Generalitat de Catalunya (DOGC)</b> y también en el BOE.</p>",
    "<p>Té <b>135 diputats</b> elegits cada quatre anys en quatre circumscripcions (Barcelona 85, Girona 17, Lleida 15 i Tarragona 18). Aprova les lleis catalanes i els pressupostos, elegeix el President i controla el Govern amb preguntes, interpel·lacions i comissions. Té la seu a l'antic arsenal de la Ciutadella, a Barcelona.</p><p>Les lleis que aprova es publiquen al <b>Diari Oficial de la Generalitat de Catalunya (DOGC)</b> i també al BOE.</p>"),
  S("El President y el Govern", "El President i el Govern",
    "<p>El <b>President de la Generalitat</b> es elegido por el Parlament entre sus diputados y nombrado formalmente por el Rey. Representa a Catalunya y dirige el Govern. El <b>Govern</b> está formado por los consellers, cada uno al frente de un departamento (Salut, Educació, Interior…). Aprueba decretos, prepara los proyectos de ley y dirige la administración catalana, que incluye los Mossos d'Esquadra, el sistema sanitario público y las escuelas.</p>",
    "<p>El <b>President de la Generalitat</b> l'elegeix el Parlament entre els seus diputats i el nomena formalment el Rei. Representa Catalunya i dirigeix el Govern. El <b>Govern</b> està format pels consellers, cadascun al capdavant d'un departament (Salut, Educació, Interior…). Aprova decrets, prepara els projectes de llei i dirigeix l'administració catalana, que inclou els Mossos d'Esquadra, el sistema sanitari públic i les escoles.</p>"),
  S("Instituciones de control", "Institucions de control",
    "<ul><li><b>Síndic de Greuges</b>: defiende tus derechos frente a las administraciones catalanas y los ayuntamientos. Puedes presentarle una queja gratis.</li><li><b>Sindicatura de Comptes</b>: revisa cómo gastan el dinero público la Generalitat y los entes locales.</li><li><b>Consell de Garanties Estatutàries</b>: dictamina si los proyectos de ley respetan el Estatut y la Constitución.</li><li><b>Oficina Antifrau de Catalunya</b>: investiga casos de corrupción y fraude en el sector público.</li><li><b>Autoritat Catalana de Protecció de Dades</b> y <b>Consell de l'Audiovisual de Catalunya</b>, entre otras autoridades independientes.</li></ul>",
    "<ul><li><b>Síndic de Greuges</b>: defensa els teus drets davant les administracions catalanes i els ajuntaments. Li pots presentar una queixa gratuïtament.</li><li><b>Sindicatura de Comptes</b>: revisa com gasten els diners públics la Generalitat i els ens locals.</li><li><b>Consell de Garanties Estatutàries</b>: dictamina si els projectes de llei respecten l'Estatut i la Constitució.</li><li><b>Oficina Antifrau de Catalunya</b>: investiga casos de corrupció i frau en el sector públic.</li><li><b>Autoritat Catalana de Protecció de Dades</b> i <b>Consell de l'Audiovisual de Catalunya</b>, entre altres autoritats independents.</li></ul>"),
  S("Justicia y gobierno local", "Justícia i govern local",
    "<p>La justicia es un poder del Estado, pero el <b>Tribunal Superior de Justícia de Catalunya (TSJC)</b> es la última instancia para el derecho civil catalán: el Tribunal Supremo no puede corregir su interpretación del Codi civil de Catalunya. La Generalitat gestiona los medios materiales de los juzgados.</p><p>Catalunya se organiza en 947 municipios, 42 comarcas (más el Aran, con un régimen especial) y 4 diputaciones provinciales. El <b>Conselh Generau d'Aran</b> gobierna el Valle de Arán, donde el aranés es lengua oficial.</p>",
    "<p>La justícia és un poder de l'Estat, però el <b>Tribunal Superior de Justícia de Catalunya (TSJC)</b> és l'última instància per al dret civil català: el Tribunal Suprem no pot corregir-ne la interpretació del Codi civil de Catalunya. La Generalitat gestiona els mitjans materials dels jutjats.</p><p>Catalunya s'organitza en 947 municipis, 42 comarques (més l'Aran, amb un règim especial) i 4 diputacions provincials. El <b>Conselh Generau d'Aran</b> governa la Vall d'Aran, on l'aranès és llengua oficial.</p>")],
 [("Diputados", "Diputats", "135", "135"), ("Legislatura", "Legislatura", "4 años", "4 anys"), ("Municipios", "Municipis", "947", "947")],
 ("La Generalitat tiene orígenes medievales: nació en 1359 como comisión de las Corts catalanas para recaudar impuestos. Fue suprimida en 1714 y restablecida en 1931 y en 1977.", "La Generalitat té orígens medievals: va néixer el 1359 com a comissió de les Corts catalanes per recaptar impostos. Va ser suprimida el 1714 i restablerta el 1931 i el 1977."),
 "Constitución Española (título VIII) y Estatut d'Autonomia de Catalunya (Llei Orgànica 6/2006)",
 [("catestatut", "El Estatut d'Autonomia", "L'Estatut d'Autonomia"), ("administracion", "Administración: recursos y plazos", "Administració: recursos i terminis")])

T_("catestatut", "catalunya", ("catalunya/estatut/", "ca/catalunya/estatut/"), ("Catalunya · Autogobierno", "Catalunya · Autogovern"),
 ("El Estatut d'Autonomia de Catalunya", "L'Estatut d'Autonomia de Catalunya"),
 ("Qué es el Estatut, qué competencias da a la Generalitat y cómo ha cambiado desde 1932.", "Què és l'Estatut, quines competències dona a la Generalitat i com ha canviat des del 1932."),
 ("El Estatut d'Autonomia es la norma institucional básica de Catalunya: dice qué instituciones tiene, qué competencias ejerce y qué derechos reconoce. Es a la vez una ley orgánica del Estado. Ha habido tres: 1932, 1979 y 2006. El de 2006 fue recortado en parte por la sentencia del Tribunal Constitucional 31/2010.",
  "L'Estatut d'Autonomia és la norma institucional bàsica de Catalunya: diu quines institucions té, quines competències exerceix i quins drets reconeix. És alhora una llei orgànica de l'Estat. N'hi ha hagut tres: 1932, 1979 i 2006. El del 2006 va ser retallat en part per la sentència del Tribunal Constitucional 31/2010."),
 [S("Tres Estatuts", "Tres Estatuts",
    "<ul><li><b>1932 (Estatut de Núria)</b>: aprobado en referéndum en Catalunya y recortado después por las Cortes de la República. Restableció la Generalitat, con Francesc Macià como President. Quedó suspendido en 1934 y abolido por Franco en 1938.</li><li><b>1979 (Estatut de Sau)</b>: aprobado en referéndum con el 88 % de votos a favor. Fue el marco del autogobierno durante 27 años.</li><li><b>2006</b>: aprobado por el Parlament, recortado por las Cortes Generales y ratificado en referéndum con el 74 % de votos a favor (participación del 49 %).</li></ul>",
    "<ul><li><b>1932 (Estatut de Núria)</b>: aprovat en referèndum a Catalunya i retallat després per les Corts de la República. Va restablir la Generalitat, amb Francesc Macià com a President. Va quedar suspès el 1934 i abolit per Franco el 1938.</li><li><b>1979 (Estatut de Sau)</b>: aprovat en referèndum amb el 88 % de vots a favor. Va ser el marc de l'autogovern durant 27 anys.</li><li><b>2006</b>: aprovat pel Parlament, retallat per les Corts Generals i ratificat en referèndum amb el 74 % de vots a favor (participació del 49 %).</li></ul>"),
  S("Qué competencias tiene la Generalitat", "Quines competències té la Generalitat",
    "<p>Las competencias pueden ser <b>exclusivas</b> (la Generalitat legisla y ejecuta), <b>compartidas</b> (el Estado fija las bases y Catalunya las desarrolla) o <b>ejecutivas</b> (Catalunya aplica leyes del Estado).</p><ul><li>Exclusivas o casi: derecho civil catalán, lengua propia, cultura, urbanismo y vivienda, comercio interior, turismo, policía propia (Mossos), organización territorial.</li><li>Compartidas: educación, sanidad, medio ambiente, consumo, régimen de las administraciones.</li><li>Ejecutivas: legislación laboral, prisiones, propiedad intelectual.</li></ul><p>El Estado mantiene, entre otras, la defensa, las relaciones internacionales, la nacionalidad y extranjería, el derecho penal y procesal, la Seguridad Social y la legislación laboral.</p>",
    "<p>Les competències poden ser <b>exclusives</b> (la Generalitat legisla i executa), <b>compartides</b> (l'Estat fixa les bases i Catalunya les desplega) o <b>executives</b> (Catalunya aplica lleis de l'Estat).</p><ul><li>Exclusives o gairebé: dret civil català, llengua pròpia, cultura, urbanisme i habitatge, comerç interior, turisme, policia pròpia (Mossos), organització territorial.</li><li>Compartides: educació, sanitat, medi ambient, consum, règim de les administracions.</li><li>Executives: legislació laboral, presons, propietat intel·lectual.</li></ul><p>L'Estat manté, entre altres, la defensa, les relacions internacionals, la nacionalitat i l'estrangeria, el dret penal i processal, la Seguretat Social i la legislació laboral.</p>"),
  S("La sentencia de 2010", "La sentència del 2010",
    "<p>En junio de 2010 el Tribunal Constitucional resolvió el recurso del Partido Popular contra el Estatut. Declaró inconstitucionales 14 artículos, total o parcialmente, y reinterpretó otros 27. Entre lo más relevante: el preámbulo que define a Catalunya como nación «no tiene eficacia jurídica interpretativa», el catalán no puede ser lengua «preferente» de las administraciones y el Consell de Justícia de Catalunya no puede ser un órgano de gobierno del poder judicial. La sentencia provocó una gran manifestación en Barcelona y está en el origen del proceso político de los años siguientes.</p>",
    "<p>El juny del 2010 el Tribunal Constitucional va resoldre el recurs del Partit Popular contra l'Estatut. Va declarar inconstitucionals 14 articles, totalment o parcialment, i en va reinterpretar 27 més. Entre el més rellevant: el preàmbul que defineix Catalunya com a nació «no té eficàcia jurídica interpretativa», el català no pot ser llengua «preferent» de les administracions i el Consell de Justícia de Catalunya no pot ser un òrgan de govern del poder judicial. La sentència va provocar una gran manifestació a Barcelona i és a l'origen del procés polític dels anys següents.</p>"),
  S("Derechos que reconoce el Estatut", "Drets que reconeix l'Estatut",
    "<p>El Estatut de 2006 incluye una carta de derechos de los ciudadanos de Catalunya: derecho a una muerte digna y a expresar voluntades anticipadas, derechos en el ámbito de la salud, la educación y los servicios sociales, derechos lingüísticos, derecho a una buena administración y a acceder a la información pública. Vinculan a los poderes públicos catalanes y se pueden invocar ante el Síndic de Greuges.</p>",
    "<p>L'Estatut del 2006 inclou una carta de drets dels ciutadans de Catalunya: dret a una mort digna i a expressar voluntats anticipades, drets en l'àmbit de la salut, l'educació i els serveis socials, drets lingüístics, dret a una bona administració i a accedir a la informació pública. Vinculen els poders públics catalans i es poden invocar davant el Síndic de Greuges.</p>")],
 [("Estatut vigente", "Estatut vigent", "Ley Orgánica 6/2006", "Llei Orgànica 6/2006"), ("Sentencia del TC", "Sentència del TC", "31/2010", "31/2010"), ("Artículos", "Articles", "223", "223")],
 ("Para reformar el Estatut hace falta mayoría de dos tercios en el Parlament, aprobación de las Cortes Generales y referéndum en Catalunya.", "Per reformar l'Estatut cal una majoria de dos terços al Parlament, l'aprovació de les Corts Generals i referèndum a Catalunya."),
 "Llei Orgànica 6/2006, de reforma de l'Estatut d'Autonomia de Catalunya, y STC 31/2010",
 [("catinst", "Las instituciones de Catalunya", "Les institucions de Catalunya"), ("historia", "Historia del derecho", "Història del dret")])

T_("catcivil", "catalunya", ("catalunya/derecho-civil-catalan/", "ca/catalunya/dret-civil-catala/"), ("Catalunya · Derecho civil", "Catalunya · Dret civil"),
 ("El derecho civil catalán y la vecindad civil", "El dret civil català i el veïnatge civil"),
 ("Por qué en Catalunya la herencia, el matrimonio o la compraventa siguen reglas propias, y a quién se aplican.", "Per què a Catalunya l'herència, el matrimoni o la compravenda segueixen regles pròpies, i a qui s'apliquen."),
 ("Catalunya conserva un derecho civil propio, recogido en el Codi civil de Catalunya. No se aplica según dónde vives, sino según tu vecindad civil: la tienes catalana si naciste de padres con vecindad catalana o si has vivido en Catalunya 2 años y lo declaras (o 10 años sin declarar lo contrario).",
  "Catalunya conserva un dret civil propi, recollit al Codi civil de Catalunya. No s'aplica segons on vius, sinó segons el teu veïnatge civil: el tens català si vas néixer de pares amb veïnatge català o si has viscut a Catalunya 2 anys i ho declares (o 10 anys sense declarar el contrari)."),
 [S("El Codi civil de Catalunya", "El Codi civil de Catalunya",
    "<p>Se aprobó por libros entre 2002 y 2017 y sustituyó a la antigua Compilación de 1960. Tiene seis libros:</p><ol><li>Disposiciones generales (prescripción, caducidad).</li><li>Persona y familia.</li><li>Persona jurídica (asociaciones y fundaciones).</li><li>Sucesiones.</li><li>Derechos reales (propiedad, servidumbres, propiedad horizontal).</li><li>Obligaciones y contratos (compraventa, permuta, mandato).</li></ol><p>Donde el Codi no dice nada, se aplica el Código Civil español como derecho supletorio.</p>",
    "<p>Es va aprovar per llibres entre el 2002 i el 2017 i va substituir l'antiga Compilació del 1960. Té sis llibres:</p><ol><li>Disposicions generals (prescripció, caducitat).</li><li>Persona i família.</li><li>Persona jurídica (associacions i fundacions).</li><li>Successions.</li><li>Drets reals (propietat, servituds, propietat horitzontal).</li><li>Obligacions i contractes (compravenda, permuta, mandat).</li></ol><p>On el Codi no diu res, s'aplica el Código Civil espanyol com a dret supletori.</p>"),
  S("Qué es la vecindad civil", "Què és el veïnatge civil",
    "<ul><li><b>Por nacimiento</b>: tienes la de tus padres. Si tienen distinta, la que elijan; si no eligen, la del lugar de nacimiento.</li><li><b>Por residencia</b>: 2 años viviendo en Catalunya y una declaración en el Registro Civil, o 10 años seguidos sin declarar que quieres conservar la anterior.</li><li><b>Por matrimonio</b>: puedes optar por la vecindad de tu cónyuge.</li><li>Los extranjeros que obtienen la nacionalidad española pueden elegir la vecindad del lugar donde viven.</li></ul><p>La vecindad decide qué régimen económico tiene tu matrimonio, cómo se reparte tu herencia o quién hereda si no hay testamento. Si no sabes cuál tienes, puedes pedir un certificado en el Registro Civil.</p>",
    "<ul><li><b>Per naixement</b>: tens el dels teus pares. Si en tenen de diferent, el que triïn; si no trien, el del lloc de naixement.</li><li><b>Per residència</b>: 2 anys vivint a Catalunya i una declaració al Registre Civil, o 10 anys seguits sense declarar que vols conservar l'anterior.</li><li><b>Per matrimoni</b>: pots optar pel veïnatge del teu cònjuge.</li><li>Els estrangers que obtenen la nacionalitat espanyola poden triar el veïnatge del lloc on viuen.</li></ul><p>El veïnatge decideix quin règim econòmic té el teu matrimoni, com es reparteix la teva herència o qui hereta si no hi ha testament. Si no saps quin tens, pots demanar un certificat al Registre Civil.</p>"),
  S("Diferencias que más se notan", "Diferències que més es noten",
    "<ul><li><b>Matrimonio</b>: separación de bienes en lugar de gananciales.</li><li><b>Herencia</b>: la legítima de los hijos es una cuarta parte, frente a dos tercios en el Código Civil.</li><li><b>Parejas</b>: la parella estable nace por convivencia de 2 años o por un hijo común.</li><li><b>Compraventa de vivienda</b>: reglas propias sobre conformidad y saneamiento desde 2017.</li><li><b>Comunidades de vecinos</b>: la propiedad horizontal se rige por el libro quinto, con quórums y plazos distintos.</li><li><b>Prescripción</b>: la general es de 10 años (5 en el Código Civil desde 2015) y la de las deudas periódicas, de 3 años.</li></ul>",
    "<ul><li><b>Matrimoni</b>: separació de béns en lloc de guanys.</li><li><b>Herència</b>: la llegítima dels fills és una quarta part, davant de dos terços al Código Civil.</li><li><b>Parelles</b>: la parella estable neix per convivència de 2 anys o per un fill comú.</li><li><b>Compravenda d'habitatge</b>: regles pròpies sobre conformitat i sanejament des del 2017.</li><li><b>Comunitats de veïns</b>: la propietat horitzontal es regeix pel llibre cinquè, amb quòrums i terminis diferents.</li><li><b>Prescripció</b>: la general és de 10 anys (5 al Código Civil des del 2015) i la de deutes periòdics, de 3 anys.</li></ul>"),
  S("Una tradición de siglos", "Una tradició de segles",
    "<p>El derecho catalán viene de los <b>Usatges de Barcelona</b> (siglo XI), las constituciones de las Corts y el derecho romano y canónico. Los Decretos de Nueva Planta (1716) suprimieron las instituciones catalanas, pero respetaron el derecho privado. Durante el siglo XIX juristas como Manuel Duran i Bas defendieron que no se unificara en un único Código Civil, y por eso hoy Catalunya, como Aragón, Navarra, el País Vasco, Galicia o Baleares, tiene derecho civil propio.</p>",
    "<p>El dret català ve dels <b>Usatges de Barcelona</b> (segle XI), les constitucions de les Corts i el dret romà i canònic. Els Decrets de Nova Planta (1716) van suprimir les institucions catalanes, però van respectar el dret privat. Durant el segle XIX juristes com Manuel Duran i Bas van defensar que no s'unifiqués en un únic Codi Civil, i per això avui Catalunya, com l'Aragó, Navarra, el País Basc, Galícia o les Balears, té dret civil propi.</p>")],
 [("Libros del Codi", "Llibres del Codi", "6", "6"), ("Vecindad por residencia", "Veïnatge per residència", "2 años con declaración, 10 sin ella", "2 anys amb declaració, 10 sense"), ("Prescripción general", "Prescripció general", "10 años", "10 anys")],
 ("El Tribunal Superior de Justícia de Catalunya es la última palabra en la interpretación del derecho civil catalán.", "El Tribunal Superior de Justícia de Catalunya té l'última paraula en la interpretació del dret civil català."),
 "Codi civil de Catalunya (lleis 29/2002, 25/2010, 4/2008, 10/2008, 5/2006 i 3/2017) y Código Civil, artículos 14 y 15",
 [("familia", "Familia", "Família"), ("sucesiones", "Sucesiones", "Successions")])

T_("catlengua", "catalunya", ("catalunya/lenguas/", "ca/catalunya/llengues/"), ("Catalunya · Lenguas", "Catalunya · Llengües"),
 ("Lenguas oficiales y derechos lingüísticos", "Llengües oficials i drets lingüístics"),
 ("Catalán, castellano y aranés: qué derechos tienes en la administración, en los comercios, en la escuela y en la justicia.", "Català, castellà i aranès: quins drets tens a l'administració, als comerços, a l'escola i a la justícia."),
 ("En Catalunya son oficiales el catalán, el castellano y el aranés (la variedad del occitano del Valle de Arán). Puedes dirigirte a cualquier administración en catalán o castellano y te deben responder en la lengua que elijas. Los comercios deben poder atenderte en cualquiera de las dos, y la rotulación fija y la información básica deben estar al menos en catalán.",
  "A Catalunya són oficials el català, el castellà i l'aranès (la varietat de l'occità de la Vall d'Aran). Pots adreçar-te a qualsevol administració en català o castellà i t'han de respondre en la llengua que triïs. Els comerços t'han de poder atendre en qualsevol de les dues, i la retolació fixa i la informació bàsica han de ser almenys en català."),
 [S("Ante la administración", "Davant l'administració",
    "<p>Tienes derecho a relacionarte con las administraciones en Catalunya (también con las oficinas del Estado) en catalán o en castellano, oralmente y por escrito, y a recibir las respuestas en la lengua que elijas. Los documentos públicos tienen validez en cualquiera de las dos lenguas, y puedes pedir una traducción si no entiendes la otra.</p>",
    "<p>Tens dret a relacionar-te amb les administracions a Catalunya (també amb les oficines de l'Estat) en català o en castellà, oralment i per escrit, i a rebre les respostes en la llengua que triïs. Els documents públics tenen validesa en qualsevol de les dues llengües, i pots demanar-ne una traducció si no entens l'altra.</p>"),
  S("En comercios y empresas", "En comerços i empreses",
    "<p>El Codi de consum de Catalunya reconoce el <b>derecho a ser atendido</b> oralmente y por escrito en la lengua oficial que elijas. Los establecimientos abiertos al público deben tener al menos en catalán la rotulación fija, las cartas de los restaurantes, los contratos de adhesión, las facturas si se piden y la información de carácter fijo. Si una empresa no lo cumple, puedes presentar una queja con el full oficial de reclamació o ante la Agència Catalana del Consum.</p>",
    "<p>El Codi de consum de Catalunya reconeix el <b>dret a ser atès</b> oralment i per escrit en la llengua oficial que triïs. Els establiments oberts al públic han de tenir almenys en català la retolació fixa, les cartes dels restaurants, els contractes d'adhesió, les factures si es demanen i la informació de caràcter fix. Si una empresa no ho compleix, pots presentar una queixa amb el full oficial de reclamació o davant l'Agència Catalana del Consum.</p>"),
  S("En la escuela", "A l'escola",
    "<p>El catalán es la lengua vehicular del sistema educativo catalán (modelo de inmersión lingüística), y al acabar la enseñanza obligatoria el alumnado debe dominar el catalán y el castellano. En los últimos años los tribunales han discutido el porcentaje mínimo de clases en castellano; en 2022 el Parlament aprobó una ley que define el catalán como lengua vehicular y el castellano como lengua curricular, cuyo encaje constitucional ha sido objeto de pronunciamientos del Tribunal Constitucional.</p>",
    "<p>El català és la llengua vehicular del sistema educatiu català (model d'immersió lingüística), i en acabar l'ensenyament obligatori l'alumnat ha de dominar el català i el castellà. Els darrers anys els tribunals han discutit el percentatge mínim de classes en castellà; el 2022 el Parlament va aprovar una llei que defineix el català com a llengua vehicular i el castellà com a llengua curricular, l'encaix constitucional de la qual ha estat objecte de pronunciaments del Tribunal Constitucional.</p>"),
  S("En la justicia y el aranés", "A la justícia i l'aranès",
    "<p>En los juzgados de Catalunya puedes usar el catalán o el castellano. Las actuaciones en catalán son válidas sin traducción, salvo que una parte alegue indefensión. Jueces y funcionarios no están obligados a hablar catalán, pero su conocimiento cuenta como mérito.</p><p>El <b>aranés</b> es oficial en toda Catalunya y lengua propia del Aran desde el Estatut de 2006 y la Llei 35/2010 del occità.</p>",
    "<p>Als jutjats de Catalunya pots fer servir el català o el castellà. Les actuacions en català són vàlides sense traducció, tret que una part al·legui indefensió. Els jutges i funcionaris no estan obligats a parlar català, però el seu coneixement compta com a mèrit.</p><p>L'<b>aranès</b> és oficial a tot Catalunya i llengua pròpia de l'Aran des de l'Estatut del 2006 i la Llei 35/2010 de l'occità.</p>")],
 [("Lenguas oficiales", "Llengües oficials", "Catalán, castellano y aranés", "Català, castellà i aranès"), ("Ley de política lingüística", "Llei de política lingüística", "Llei 1/1998", "Llei 1/1998")],
 ("Si crees que se han vulnerado tus derechos lingüísticos, puedes dirigirte a la Oficina de Garanties Lingüístiques de la Generalitat o al Síndic de Greuges.", "Si creus que s'han vulnerat els teus drets lingüístics, pots adreçar-te a l'Oficina de Garanties Lingüístiques de la Generalitat o al Síndic de Greuges."),
 "Constitución Española (art. 3), Estatut d'Autonomia (arts. 6 y 32 a 36), Llei 1/1998 de política lingüística y Llei 22/2010 del Codi de consum de Catalunya",
 [("consumo", "Consumo", "Consum"), ("catinst", "Las instituciones de Catalunya", "Les institucions de Catalunya")])

# ============================ UE E INTERNACIONAL ============================
T_("uederechos", "internacional", ("ue-e-internacional/derechos-ciudadanos-ue/", "ca/ue-i-internacional/drets-ciutadans-ue/"), ("UE · Ciudadanía", "UE · Ciutadania"),
 ("Tus derechos como ciudadano de la Unión Europea", "Els teus drets com a ciutadà de la Unió Europea"),
 ("Viajar, vivir, trabajar, votar y recibir atención médica en cualquier país de la UE: lo que te garantiza ser ciudadano europeo.", "Viatjar, viure, treballar, votar i rebre atenció mèdica a qualsevol país de la UE: el que et garanteix ser ciutadà europeu."),
 ("Todo ciudadano español es también ciudadano de la Unión Europea. Eso te permite circular y residir libremente en los 27 países, trabajar sin permiso, votar y presentarte en las elecciones municipales y europeas del país donde vives, recibir asistencia consular de cualquier país de la UE fuera de Europa y usar el móvil sin recargos de roaming.",
  "Tot ciutadà espanyol és també ciutadà de la Unió Europea. Això et permet circular i residir lliurement als 27 països, treballar sense permís, votar i presentar-te a les eleccions municipals i europees del país on vius, rebre assistència consular de qualsevol país de la UE fora d'Europa i fer servir el mòbil sense recàrrecs d'itinerància."),
 [S("Viajar y vivir en otro país", "Viatjar i viure en un altre país",
    "<ul><li>Para viajar basta con el DNI o el pasaporte en vigor.</li><li>Puedes quedarte hasta <b>3 meses</b> sin trámites. Para más tiempo, te inscribes como residente demostrando que trabajas, estudias o tienes recursos y seguro médico.</li><li>Tras <b>5 años</b> de residencia legal obtienes la residencia permanente.</li><li>El espacio Schengen elimina los controles en la mayoría de fronteras interiores, aunque los países pueden restablecerlos temporalmente.</li></ul>",
    "<ul><li>Per viatjar n'hi ha prou amb el DNI o el passaport vigent.</li><li>Pots quedar-te fins a <b>3 mesos</b> sense tràmits. Per a més temps, t'inscrius com a resident demostrant que treballes, estudies o tens recursos i assegurança mèdica.</li><li>Després de <b>5 anys</b> de residència legal obtens la residència permanent.</li><li>L'espai Schengen elimina els controls a la majoria de fronteres interiors, tot i que els països els poden restablir temporalment.</li></ul>"),
  S("Salud, móvil y compras", "Salut, mòbil i compres",
    "<ul><li><b>Tarjeta Sanitaria Europea</b>: gratuita, se pide a la Seguridad Social y te da atención médica necesaria en la sanidad pública de otro país en las mismas condiciones que a sus ciudadanos.</li><li><b>Roaming</b>: llamadas, SMS y datos al mismo precio que en casa en toda la UE, con límites de uso razonable en los datos.</li><li><b>Compras</b>: mismas garantías y derecho de desistimiento de 14 días en toda la UE. No te pueden bloquear una web ni cobrarte otro precio por tu país de residencia (prohibición del geobloqueo).</li></ul>",
    "<ul><li><b>Targeta Sanitària Europea</b>: gratuïta, es demana a la Seguretat Social i et dona l'atenció mèdica necessària a la sanitat pública d'un altre país en les mateixes condicions que als seus ciutadans.</li><li><b>Itinerància</b>: trucades, SMS i dades al mateix preu que a casa a tota la UE, amb límits d'ús raonable en les dades.</li><li><b>Compres</b>: les mateixes garanties i el dret de desistiment de 14 dies a tota la UE. No et poden bloquejar un web ni cobrar-te un altre preu pel teu país de residència (prohibició del geoblocatge).</li></ul>"),
  S("Votar y participar", "Votar i participar",
    "<p>Si vives en otro país de la UE puedes votar y ser candidato en sus <b>elecciones municipales</b> y en las <b>europeas</b>, inscribiéndote en su censo. También puedes:</p><ul><li>Firmar o promover una <b>Iniciativa Ciudadana Europea</b>: con un millón de firmas de al menos siete países, la Comisión debe estudiar la propuesta.</li><li>Presentar una <b>petición al Parlamento Europeo</b>.</li><li>Quejarte ante el <b>Defensor del Pueblo Europeo</b> por mala administración de las instituciones de la UE.</li></ul>",
    "<p>Si vius en un altre país de la UE pots votar i ser candidat a les seves <b>eleccions municipals</b> i a les <b>europees</b>, inscrivint-te al seu cens. També pots:</p><ul><li>Signar o promoure una <b>Iniciativa Ciutadana Europea</b>: amb un milió de signatures d'almenys set països, la Comissió ha d'estudiar la proposta.</li><li>Presentar una <b>petició al Parlament Europeu</b>.</li><li>Queixar-te al <b>Defensor del Poble Europeu</b> per mala administració de les institucions de la UE.</li></ul>"),
  S("Si un país no respeta tus derechos", "Si un país no respecta els teus drets",
    "<p>El servicio gratuito <b>SOLVIT</b> resuelve en unas 10 semanas problemas con administraciones de otro país de la UE (reconocimiento de títulos, residencia, prestaciones). <b>Tu Europa Asesoramiento</b> responde consultas personalizadas. Y si el problema es una ley nacional contraria al derecho europeo, puedes presentar una queja a la Comisión Europea.</p>",
    "<p>El servei gratuït <b>SOLVIT</b> resol en unes 10 setmanes problemes amb administracions d'un altre país de la UE (reconeixement de títols, residència, prestacions). <b>Your Europe Advice</b> respon consultes personalitzades. I si el problema és una llei nacional contrària al dret europeu, pots presentar una queixa a la Comissió Europea.</p>")],
 [("Países de la UE", "Països de la UE", "27", "27"), ("Estancia sin trámites", "Estada sense tràmits", "3 meses", "3 mesos"), ("Residencia permanente", "Residència permanent", "5 años", "5 anys")],
 ("La ciudadanía de la Unión se suma a la nacional y no la sustituye.", "La ciutadania de la Unió se suma a la nacional i no la substitueix."),
 "Tratado de Funcionamiento de la Unión Europea (arts. 18 a 25), Directiva 2004/38/CE y Carta de los Derechos Fundamentales de la UE",
 [("extranjeria", "Extranjería", "Estrangeria"), ("uetrabajo", "Trabajar o jubilarse en otro país de la UE", "Treballar o jubilar-se en un altre país de la UE")])

T_("ueleyes", "internacional", ("ue-e-internacional/como-se-hacen-las-leyes-europeas/", "ca/ue-i-internacional/com-es-fan-les-lleis-europees/"), ("UE · Instituciones", "UE · Institucions"),
 ("Cómo se hacen las leyes europeas", "Com es fan les lleis europees"),
 ("Reglamentos, directivas, Parlamento, Consejo, Comisión y Tribunal de Justicia: el camino de una norma europea hasta que te afecta.", "Reglaments, directives, Parlament, Consell, Comissió i Tribunal de Justícia: el camí d'una norma europea fins que t'afecta."),
 ("La Comisión Europea propone las leyes; el Parlamento Europeo y el Consejo de la UE las aprueban juntos. Un reglamento se aplica directamente en todos los países; una directiva fija un objetivo que cada país debe incorporar a su ley en un plazo. El derecho europeo prevalece sobre el nacional, y el Tribunal de Justicia de la UE garantiza que se interprete igual en todas partes.",
  "La Comissió Europea proposa les lleis; el Parlament Europeu i el Consell de la UE les aproven conjuntament. Un reglament s'aplica directament a tots els països; una directiva fixa un objectiu que cada país ha d'incorporar a la seva llei en un termini. El dret europeu preval sobre el nacional, i el Tribunal de Justícia de la UE garanteix que s'interpreti igual a tot arreu."),
 [S("Las instituciones", "Les institucions",
    "<ul><li><b>Comisión Europea</b>: un comisario por país. Propone leyes, gestiona el presupuesto y vigila que se cumplan los tratados.</li><li><b>Parlamento Europeo</b>: 720 eurodiputados elegidos cada 5 años; a España le corresponden 61. Aprueba leyes y presupuesto y controla a la Comisión.</li><li><b>Consejo de la UE</b>: los ministros de cada país según el tema. Aprueba leyes junto al Parlamento.</li><li><b>Consejo Europeo</b>: jefes de Estado o de Gobierno. Marca las grandes orientaciones, pero no legisla.</li><li><b>Tribunal de Justicia de la UE</b>, en Luxemburgo, y <b>Banco Central Europeo</b>, en Fráncfort.</li></ul>",
    "<ul><li><b>Comissió Europea</b>: un comissari per país. Proposa lleis, gestiona el pressupost i vetlla perquè es compleixin els tractats.</li><li><b>Parlament Europeu</b>: 720 eurodiputats elegits cada 5 anys; a Espanya li'n corresponen 61. Aprova lleis i pressupost i controla la Comissió.</li><li><b>Consell de la UE</b>: els ministres de cada país segons el tema. Aprova lleis juntament amb el Parlament.</li><li><b>Consell Europeu</b>: caps d'Estat o de Govern. Marca les grans orientacions, però no legisla.</li><li><b>Tribunal de Justícia de la UE</b>, a Luxemburg, i <b>Banc Central Europeu</b>, a Frankfurt.</li></ul>"),
  S("Reglamentos y directivas", "Reglaments i directives",
    "<ul><li><b>Reglamento</b>: obligatorio en todos sus elementos y directamente aplicable, sin ley nacional. Ejemplos: el RGPD de protección de datos o el reglamento de derechos de los pasajeros aéreos.</li><li><b>Directiva</b>: obliga a conseguir un resultado; cada país la «transpone» a su ley. Ejemplo: las directivas de consumo, que en España están en la Ley General para la Defensa de los Consumidores.</li><li><b>Decisión</b>: obligatoria solo para sus destinatarios.</li><li><b>Recomendaciones y dictámenes</b>: no obligan.</li></ul><p>Si un país no transpone una directiva a tiempo, algunas de sus normas claras pueden invocarse igualmente ante los tribunales frente al Estado.</p>",
    "<ul><li><b>Reglament</b>: obligatori en tots els elements i directament aplicable, sense llei nacional. Exemples: el RGPD de protecció de dades o el reglament de drets dels passatgers aeris.</li><li><b>Directiva</b>: obliga a aconseguir un resultat; cada país la «transposa» a la seva llei. Exemple: les directives de consum, que a Espanya són a la Ley General para la Defensa de los Consumidores.</li><li><b>Decisió</b>: obligatòria només per als seus destinataris.</li><li><b>Recomanacions i dictàmens</b>: no obliguen.</li></ul><p>Si un país no transposa una directiva a temps, algunes de les seves normes clares es poden invocar igualment davant els tribunals davant l'Estat.</p>"),
  S("El procedimiento legislativo", "El procediment legislatiu",
    "<ol><li>La Comisión publica una propuesta, tras consultar a ciudadanos y sectores.</li><li>El Parlamento la debate en comisión y aprueba enmiendas.</li><li>El Consejo fija su posición. Normalmente hay negociaciones a tres bandas («trílogos») para acercar posturas.</li><li>Cuando Parlamento y Consejo aprueban el mismo texto, se publica en el <b>Diario Oficial de la Unión Europea</b> y se puede consultar gratis en EUR-Lex.</li></ol>",
    "<ol><li>La Comissió publica una proposta, després de consultar ciutadans i sectors.</li><li>El Parlament la debat en comissió i aprova esmenes.</li><li>El Consell fixa la seva posició. Normalment hi ha negociacions a tres bandes («trílegs») per acostar posicions.</li><li>Quan Parlament i Consell aproven el mateix text, es publica al <b>Diari Oficial de la Unió Europea</b> i es pot consultar gratuïtament a EUR-Lex.</li></ol>"),
  S("El Tribunal de Justicia y la cuestión prejudicial", "El Tribunal de Justícia i la qüestió prejudicial",
    "<p>Cuando un juez español duda sobre cómo interpretar una norma europea, puede preguntar al Tribunal de Justicia de la UE con una <b>cuestión prejudicial</b>. La respuesta vincula a todos los jueces de la Unión. Muchos cambios que han beneficiado a consumidores españoles salieron de ahí: las cláusulas suelo, los intereses abusivos o los desahucios por cláusulas de vencimiento anticipado.</p><p>No hay que confundirlo con el <b>Tribunal Europeo de Derechos Humanos</b> de Estrasburgo, que depende del Consejo de Europa (46 países) y vela por el Convenio Europeo de Derechos Humanos.</p>",
    "<p>Quan un jutge espanyol dubta sobre com interpretar una norma europea, pot preguntar al Tribunal de Justícia de la UE amb una <b>qüestió prejudicial</b>. La resposta vincula tots els jutges de la Unió. Molts canvis que han beneficiat els consumidors espanyols en van sortir: les clàusules sòl, els interessos abusius o els desnonaments per clàusules de venciment anticipat.</p><p>No s'ha de confondre amb el <b>Tribunal Europeu de Drets Humans</b> d'Estrasburg, que depèn del Consell d'Europa (46 països) i vetlla pel Conveni Europeu de Drets Humans.</p>")],
 [("Eurodiputados", "Eurodiputats", "720 (61 de España)", "720 (61 d'Espanya)"), ("Diario oficial", "Diari oficial", "DOUE, consultable en EUR-Lex", "DOUE, consultable a EUR-Lex")],
 ("Leypedia muestra cada día las últimas publicaciones del Diario Oficial de la UE en Novedades.", "Leypedia mostra cada dia les darreres publicacions del Diari Oficial de la UE a Novetats."),
 "Tratado de la Unión Europea y Tratado de Funcionamiento de la Unión Europea (arts. 288 a 299)",
 [("novedades", "Novedades: BOE, DOGC y DOUE", "Novetats: BOE, DOGC i DOUE"), ("ue", "Reglamento europeo de inteligencia artificial", "Reglament europeu d'intel·ligència artificial")])

T_("uetrabajo", "internacional", ("ue-e-internacional/trabajar-en-otro-pais-ue/", "ca/ue-i-internacional/treballar-en-un-altre-pais-ue/"), ("UE · Trabajo", "UE · Treball"),
 ("Trabajar o jubilarse en otro país de la UE", "Treballar o jubilar-se en un altre país de la UE"),
 ("Qué pasa con tu cotización, tu paro y tu pensión si trabajas en varios países europeos.", "Què passa amb la teva cotització, el teu atur i la teva pensió si treballes en diversos països europeus."),
 ("En la UE solo cotizas en un país a la vez, normalmente donde trabajas. Los periodos cotizados en distintos países se suman para tener derecho a prestaciones, y al jubilarte cada país te paga la parte de pensión que corresponde a lo que cotizaste allí. Para llevarte el paro a otro país, pide el formulario U2; para acreditar periodos trabajados fuera, el U1.",
  "A la UE només cotitzes en un país alhora, normalment on treballes. Els períodes cotitzats en diferents països se sumen per tenir dret a prestacions, i quan et jubiles cada país et paga la part de pensió que correspon al que hi vas cotitzar. Per endur-te l'atur a un altre país, demana el formulari U2; per acreditar períodes treballats fora, l'U1."),
 [S("Dónde cotizas", "On cotitzes",
    "<ul><li>Regla general: en el país donde trabajas, aunque vivas en otro.</li><li><b>Desplazados</b>: si tu empresa española te envía a otro país hasta 24 meses, sigues cotizando en España con el certificado <b>A1</b>.</li><li>Si trabajas en varios países a la vez, cotizas en el de residencia si haces allí una parte sustancial (25 %) de tu trabajo.</li><li><b>Trabajadores fronterizos</b>: cotizan donde trabajan y reciben asistencia sanitaria en los dos países.</li></ul>",
    "<ul><li>Regla general: al país on treballes, encara que visquis en un altre.</li><li><b>Desplaçats</b>: si la teva empresa espanyola t'envia a un altre país fins a 24 mesos, continues cotitzant a Espanya amb el certificat <b>A1</b>.</li><li>Si treballes en diversos països alhora, cotitzes al de residència si hi fas una part substancial (25 %) de la feina.</li><li><b>Treballadors fronterers</b>: cotitzen on treballen i reben assistència sanitària als dos països.</li></ul>"),
  S("El paro en otro país", "L'atur en un altre país",
    "<p>Para cobrar el paro se tienen en cuenta los periodos trabajados en otros países: pide al país donde trabajaste el documento <b>U1</b>. Si cobras el paro español y quieres buscar trabajo en otro país de la UE, puedes «exportarlo» durante <b>3 meses</b> (ampliables a 6) con el formulario <b>U2</b>, pidiéndolo al SEPE antes de irte.</p>",
    "<p>Per cobrar l'atur es tenen en compte els períodes treballats en altres països: demana al país on vas treballar el document <b>U1</b>. Si cobres l'atur espanyol i vols buscar feina en un altre país de la UE, el pots «exportar» durant <b>3 mesos</b> (ampliables a 6) amb el formulari <b>U2</b>, demanant-lo al SEPE abans de marxar.</p>"),
  S("La jubilación con carreras en varios países", "La jubilació amb carreres a diversos països",
    "<p>Cada país en el que hayas cotizado al menos 1 año guarda tus periodos y, al jubilarte, te paga su parte. Para saber si llegas al mínimo de años, cada país suma los periodos de todos (<b>totalización</b>) y después calcula la parte proporcional (<b>prorrata</b>). Solo tienes que presentar una solicitud en el país donde vives o donde trabajaste por última vez; esa institución avisa a las demás. Las edades de jubilación pueden ser distintas en cada país, así que puedes empezar a cobrar las pensiones en momentos diferentes.</p>",
    "<p>Cada país on hagis cotitzat almenys 1 any guarda els teus períodes i, quan et jubiles, et paga la seva part. Per saber si arribes al mínim d'anys, cada país suma els períodes de tots (<b>totalització</b>) i després calcula la part proporcional (<b>prorrata</b>). Només has de presentar una sol·licitud al país on vius o on vas treballar per última vegada; aquesta institució avisa les altres. Les edats de jubilació poden ser diferents a cada país, de manera que pots començar a cobrar les pensions en moments diferents.</p>"),
  S("Títulos e impuestos", "Títols i impostos",
    "<ul><li><b>Títulos</b>: las profesiones reguladas (medicina, enfermería, arquitectura, abogacía…) requieren reconocimiento en el país de destino. Para el resto, el empleador valora el título directamente. Europass ayuda a presentar tu currículum.</li><li><b>Impuestos</b>: tributas en el país donde eres residente fiscal (más de 183 días al año) por toda tu renta mundial. Los convenios para evitar la doble imposición reparten qué país grava cada ingreso.</li></ul>",
    "<ul><li><b>Títols</b>: les professions regulades (medicina, infermeria, arquitectura, advocacia…) requereixen reconeixement al país de destinació. Per a la resta, l'ocupador valora el títol directament. Europass ajuda a presentar el currículum.</li><li><b>Impostos</b>: tributes al país on ets resident fiscal (més de 183 dies l'any) per tota la teva renda mundial. Els convenis per evitar la doble imposició reparteixen quin país grava cada ingrés.</li></ul>")],
 [("Certificado de desplazado", "Certificat de desplaçat", "A1 (hasta 24 meses)", "A1 (fins a 24 mesos)"), ("Paro exportable", "Atur exportable", "3 meses, ampliable a 6", "3 mesos, ampliable a 6"), ("Residencia fiscal", "Residència fiscal", "Más de 183 días", "Més de 183 dies")],
 ("Estas reglas se aplican también a Islandia, Liechtenstein, Noruega y Suiza, y en parte al Reino Unido por el acuerdo de retirada.", "Aquestes regles s'apliquen també a Islàndia, Liechtenstein, Noruega i Suïssa, i en part al Regne Unit per l'acord de retirada."),
 "Reglamentos (CE) 883/2004 y 987/2009 sobre coordinación de los sistemas de seguridad social",
 [("jubilacion", "Cómo pedir la jubilación", "Com demanar la jubilació"), ("segsocial", "Seguridad Social", "Seguretat Social")])

T_("uecompras", "internacional", ("ue-e-internacional/reclamar-en-otro-pais-ue/", "ca/ue-i-internacional/reclamar-en-un-altre-pais-ue/"), ("UE · Consumo", "UE · Consum"),
 ("Comprar y reclamar en otro país de la UE", "Comprar i reclamar en un altre país de la UE"),
 ("Si una tienda online de otro país europeo no te envía el pedido o no te devuelve el dinero, estas son tus herramientas.", "Si una botiga en línia d'un altre país europeu no t'envia la comanda o no et retorna els diners, aquestes són les teves eines."),
 ("Al comprar en cualquier país de la UE tienes los mismos derechos básicos: 14 días para desistir de compras a distancia, garantía mínima de 2 años (3 en España para compras a vendedores españoles) e información clara del precio final. Si la empresa no responde, el Centro Europeo del Consumidor te ayuda gratis, y para reclamaciones de hasta 5.000 € existe un proceso europeo sencillo sin abogado.",
  "En comprar a qualsevol país de la UE tens els mateixos drets bàsics: 14 dies per desistir de compres a distància, garantia mínima de 2 anys (3 a Espanya per a compres a venedors espanyols) i informació clara del preu final. Si l'empresa no respon, el Centre Europeu del Consumidor t'ajuda gratuïtament, i per a reclamacions de fins a 5.000 € hi ha un procés europeu senzill sense advocat."),
 [S("Antes de comprar", "Abans de comprar",
    "<ul><li>Comprueba que la web muestra el nombre, la dirección y el número de registro de la empresa.</li><li>Paga con tarjeta: si no recibes el producto, puedes pedir al banco la <b>retrocesión del cargo</b> (chargeback).</li><li>Desconfía de precios muy por debajo del mercado y de webs creadas hace pocos días.</li><li>Fuera de la UE (China, Estados Unidos…) no se aplican estas garantías y pagarás aduanas e IVA.</li></ul>",
    "<ul><li>Comprova que el web mostra el nom, l'adreça i el número de registre de l'empresa.</li><li>Paga amb targeta: si no reps el producte, pots demanar al banc la <b>retrocessió del càrrec</b> (chargeback).</li><li>Desconfia de preus molt per sota del mercat i de webs creats fa pocs dies.</li><li>Fora de la UE (Xina, Estats Units…) no s'apliquen aquestes garanties i pagaràs duanes i IVA.</li></ul>"),
  S("Si algo sale mal", "Si alguna cosa surt malament",
    "<ol><li>Escribe a la empresa por escrito, en su idioma o en inglés si es posible, citando tus derechos (desistimiento o garantía).</li><li>Acude al <b>Centro Europeo del Consumidor en España</b>: es gratuito y contacta con su homólogo en el país de la tienda.</li><li>Si la empresa está adherida, usa un organismo de resolución alternativa de litigios.</li><li>Como último paso, el <b>proceso europeo de escasa cuantía</b>.</li></ol>",
    "<ol><li>Escriu a l'empresa per escrit, en el seu idioma o en anglès si és possible, citant els teus drets (desistiment o garantia).</li><li>Adreça't al <b>Centre Europeu del Consumidor a Espanya</b>: és gratuït i contacta amb el seu homòleg al país de la botiga.</li><li>Si l'empresa hi està adherida, fes servir un organisme de resolució alternativa de litigis.</li><li>Com a últim pas, el <b>procés europeu d'escassa quantia</b>.</li></ol>"),
  S("El proceso europeo de escasa cuantía", "El procés europeu d'escassa quantia",
    "<p>Sirve para reclamaciones de hasta <b>5.000 €</b> contra alguien de otro país de la UE (salvo Dinamarca). Se rellena un formulario estándar, se presenta en el juzgado competente (normalmente el del domicilio del demandado, o el tuyo si eres consumidor), no hace falta abogado y casi todo es por escrito. La sentencia se puede ejecutar en cualquier país de la UE sin trámites adicionales.</p>",
    "<p>Serveix per a reclamacions de fins a <b>5.000 €</b> contra algú d'un altre país de la UE (tret de Dinamarca). S'emplena un formulari estàndard, es presenta al jutjat competent (normalment el del domicili del demandat, o el teu si ets consumidor), no cal advocat i gairebé tot és per escrit. La sentència es pot executar a qualsevol país de la UE sense tràmits addicionals.</p>"),
 ],
 [("Desistimiento", "Desistiment", "14 días en toda la UE", "14 dies a tota la UE"), ("Escasa cuantía europea", "Escassa quantia europea", "Hasta 5.000 €", "Fins a 5.000 €")],
 ("En Catalunya, la Agència Catalana del Consum también orienta en compras transfronterizas y deriva al Centro Europeo del Consumidor.", "A Catalunya, l'Agència Catalana del Consum també orienta en compres transfrontereres i deriva al Centre Europeu del Consumidor."),
 "Directiva 2011/83/UE de derechos de los consumidores y Reglamento (CE) 861/2007 del proceso europeo de escasa cuantía",
 [("consumo", "Consumo", "Consum"), ("cdesistimientocompra", "Modelo de desistimiento de compra online", "Model de desistiment de compra en línia")])

# ============================ ÉTICA ============================
T_("aborto", "eticas", ("etica/aborto/", "ca/etica/avortament/"), ("Debate · Salud", "Debat · Salut"),
 ("El aborto: la ley y el debate", "L'avortament: la llei i el debat"),
 ("Qué dice la ley española sobre la interrupción voluntaria del embarazo y cuáles son los argumentos de cada postura.", "Què diu la llei espanyola sobre la interrupció voluntària de l'embaràs i quins són els arguments de cada postura."),
 ("En España la interrupción voluntaria del embarazo es legal a petición de la mujer durante las primeras 14 semanas, y hasta la semana 22 si hay riesgo grave para su vida o su salud o graves anomalías en el feto. Desde 2023 las jóvenes de 16 y 17 años no necesitan el permiso de sus padres. Es uno de los debates éticos más intensos porque enfrenta la autonomía de la mujer con la protección de la vida prenatal.",
  "A Espanya la interrupció voluntària de l'embaràs és legal a petició de la dona durant les primeres 14 setmanes, i fins a la setmana 22 si hi ha risc greu per a la seva vida o la seva salut o anomalies greus en el fetus. Des del 2023 les joves de 16 i 17 anys no necessiten el permís dels pares. És un dels debats ètics més intensos perquè enfronta l'autonomia de la dona amb la protecció de la vida prenatal."),
 [S("Lo que dice la ley", "El que diu la llei",
    "<ul><li><b>Hasta la semana 14</b>: a petición de la mujer, tras recibir información sobre derechos y ayudas. Desde 2023 ya no son obligatorios los 3 días de reflexión.</li><li><b>Hasta la semana 22</b>: por riesgo grave para la vida o salud de la mujer o graves anomalías fetales, con dictamen médico.</li><li><b>Sin límite de semanas</b>: anomalías incompatibles con la vida o enfermedad extremadamente grave e incurable, confirmadas por un comité clínico.</li></ul><p>Se presta en la sanidad pública. Los profesionales sanitarios pueden ejercer la <b>objeción de conciencia</b>, que deben comunicar por escrito y de antemano; el sistema debe garantizar que la prestación esté disponible.</p>",
    "<ul><li><b>Fins a la setmana 14</b>: a petició de la dona, després de rebre informació sobre drets i ajuts. Des del 2023 ja no són obligatoris els 3 dies de reflexió.</li><li><b>Fins a la setmana 22</b>: per risc greu per a la vida o salut de la dona o anomalies fetals greus, amb dictamen mèdic.</li><li><b>Sense límit de setmanes</b>: anomalies incompatibles amb la vida o malaltia extremadament greu i incurable, confirmades per un comitè clínic.</li></ul><p>Es presta a la sanitat pública. Els professionals sanitaris poden exercir l'<b>objecció de consciència</b>, que han de comunicar per escrit i per endavant; el sistema ha de garantir que la prestació estigui disponible.</p>"),
  S("Cómo ha cambiado", "Com ha canviat",
    "<ul><li><b>1937</b>: la Generalitat de Catalunya aprueba la primera regulación del aborto en España, derogada en 1939.</li><li><b>1985</b>: despenalización en tres supuestos (violación, riesgo para la madre y malformaciones).</li><li><b>2010</b>: ley de plazos, con 14 semanas libres.</li><li><b>2023</b>: el Tribunal Constitucional avala la ley de 2010 y una reforma elimina el permiso paterno a los 16 y 17 años y los días de reflexión.</li></ul>",
    "<ul><li><b>1937</b>: la Generalitat de Catalunya aprova la primera regulació de l'avortament a Espanya, derogada el 1939.</li><li><b>1985</b>: despenalització en tres supòsits (violació, risc per a la mare i malformacions).</li><li><b>2010</b>: llei de terminis, amb 14 setmanes lliures.</li><li><b>2023</b>: el Tribunal Constitucional avala la llei del 2010 i una reforma elimina el permís patern als 16 i 17 anys i els dies de reflexió.</li></ul>"),
  S("Los argumentos", "Els arguments",
    "<div class=\"pos\"><div><h3>A favor del derecho a decidir</h3><ul><li>La mujer debe poder decidir sobre su propio cuerpo y su proyecto de vida.</li><li>Prohibirlo no evita abortos: los lleva a la clandestinidad y pone en peligro la salud.</li><li>En las primeras semanas el embrión no tiene la capacidad de sentir que justificaría imponer el embarazo.</li></ul></div><div><h3>En contra o por más límites</h3><ul><li>La vida humana empieza en la concepción y merece protección desde ese momento.</li><li>El Estado debería ofrecer más apoyo para que ninguna mujer aborte por motivos económicos.</li><li>Las anomalías fetales no deberían ser motivo para interrumpir el embarazo.</li></ul></div></div>",
    "<div class=\"pos\"><div><h3>A favor del dret a decidir</h3><ul><li>La dona ha de poder decidir sobre el seu propi cos i el seu projecte de vida.</li><li>Prohibir-lo no evita avortaments: els porta a la clandestinitat i posa en perill la salut.</li><li>En les primeres setmanes l'embrió no té la capacitat de sentir que justificaria imposar l'embaràs.</li></ul></div><div><h3>En contra o per més límits</h3><ul><li>La vida humana comença en la concepció i mereix protecció des d'aquell moment.</li><li>L'Estat hauria d'oferir més suport perquè cap dona avorti per motius econòmics.</li><li>Les anomalies fetals no haurien de ser motiu per interrompre l'embaràs.</li></ul></div></div>")],
 [("Plazo libre", "Termini lliure", "14 semanas", "14 setmanes"), ("Ley vigente", "Llei vigent", "Ley Orgánica 2/2010, reformada en 2023", "Llei Orgànica 2/2010, reformada el 2023")],
 ("En Catalunya la prestación está integrada en la red pública del CatSalut, y la Generalitat aprobó en 1937 la primera ley de aborto del país.", "A Catalunya la prestació està integrada a la xarxa pública del CatSalut, i la Generalitat va aprovar el 1937 la primera llei d'avortament del país."),
 "Ley Orgánica 2/2010 de salud sexual y reproductiva y de la interrupción voluntaria del embarazo, reformada por la Ley Orgánica 1/2023, y STC 44/2023",
 [("eutanasia", "La eutanasia", "L'eutanàsia"), ("eticas", "Ética y derecho", "Ètica i dret")])

T_("expresion", "eticas", ("etica/libertad-de-expresion/", "ca/etica/llibertat-d-expressio/"), ("Debate · Derechos", "Debat · Drets"),
 ("Libertad de expresión: hasta dónde llega", "Llibertat d'expressió: fins on arriba"),
 ("Humor, críticas, insultos, discurso de odio y redes sociales: dónde pone la ley los límites y por qué se discute.", "Humor, crítiques, insults, discurs d'odi i xarxes socials: on posa la llei els límits i per què es discuteix."),
 ("La Constitución protege el derecho a expresar ideas y opiniones y a dar información veraz, sin censura previa. No es ilimitado: choca con el honor, la intimidad y la propia imagen de otras personas, con la protección de menores y con delitos como la incitación al odio o las amenazas. Dónde está la frontera es una de las preguntas más discutidas en una democracia.",
  "La Constitució protegeix el dret a expressar idees i opinions i a donar informació veraç, sense censura prèvia. No és il·limitat: xoca amb l'honor, la intimitat i la pròpia imatge d'altres persones, amb la protecció de menors i amb delictes com la incitació a l'odi o les amenaces. On és la frontera és una de les preguntes més discutides en una democràcia."),
 [S("Lo que protege", "El que protegeix",
    "<p>El artículo 20 de la Constitución protege la libertad de expresión, la de información, la creación artística y científica y la libertad de cátedra. El Tribunal Constitucional y el Tribunal Europeo de Derechos Humanos repiten que protege también las ideas que «chocan, inquietan u ofenden», porque así lo exigen el pluralismo y la tolerancia. La crítica a políticos y personajes públicos tiene más protección que la dirigida a particulares.</p>",
    "<p>L'article 20 de la Constitució protegeix la llibertat d'expressió, la d'informació, la creació artística i científica i la llibertat de càtedra. El Tribunal Constitucional i el Tribunal Europeu de Drets Humans repeteixen que protegeix també les idees que «xoquen, inquieten o ofenen», perquè així ho exigeixen el pluralisme i la tolerància. La crítica a polítics i personatges públics té més protecció que la dirigida a particulars.</p>"),
  S("Los límites", "Els límits",
    "<ul><li><b>Injurias y calumnias</b>: acusar falsamente de un delito o insultar gravemente puede ser delito o dar lugar a una indemnización civil.</li><li><b>Honor, intimidad e imagen</b>: publicar datos íntimos o fotos de alguien sin consentimiento puede costar una indemnización.</li><li><b>Discurso de odio</b>: incitar al odio, la hostilidad o la violencia contra un grupo por su origen, religión, sexo u orientación es delito (art. 510 del Código Penal).</li><li><b>Enaltecimiento del terrorismo</b> y humillación de sus víctimas.</li><li><b>Amenazas y acoso</b>, también en redes.</li></ul>",
    "<ul><li><b>Injúries i calúmnies</b>: acusar falsament d'un delicte o insultar greument pot ser delicte o donar lloc a una indemnització civil.</li><li><b>Honor, intimitat i imatge</b>: publicar dades íntimes o fotos d'algú sense consentiment pot costar una indemnització.</li><li><b>Discurs d'odi</b>: incitar a l'odi, l'hostilitat o la violència contra un grup pel seu origen, religió, sexe o orientació és delicte (art. 510 del Codi Penal).</li><li><b>Enaltiment del terrorisme</b> i humiliació de les seves víctimes.</li><li><b>Amenaces i assetjament</b>, també a les xarxes.</li></ul>"),
  S("Los debates", "Els debats",
    "<div class=\"pos\"><div><h3>Más libertad</h3><ul><li>Los delitos de opinión (injurias a la Corona, ofensas religiosas, enaltecimiento) deberían desaparecer o limitarse mucho.</li><li>Condenar a cantantes o tuiteros por letras o chistes tiene un efecto disuasorio sobre todos.</li><li>Las ideas se combaten con ideas, no con el Código Penal.</li></ul></div><div><h3>Más protección</h3><ul><li>El discurso de odio prepara el terreno para la discriminación y la violencia.</li><li>Las redes amplifican los ataques y dejan a las víctimas indefensas.</li><li>Las plataformas deberían responder por los contenidos ilegales que no retiran.</li></ul></div></div><p>La Unión Europea ha aprobado la <b>Ley de Servicios Digitales</b>, que obliga a las grandes plataformas a retirar con rapidez contenido ilegal y a explicar cómo moderan.</p>",
    "<div class=\"pos\"><div><h3>Més llibertat</h3><ul><li>Els delictes d'opinió (injúries a la Corona, ofenses religioses, enaltiment) haurien de desaparèixer o limitar-se molt.</li><li>Condemnar cantants o tuitaires per lletres o acudits té un efecte dissuasiu sobre tothom.</li><li>Les idees es combaten amb idees, no amb el Codi Penal.</li></ul></div><div><h3>Més protecció</h3><ul><li>El discurs d'odi prepara el terreny per a la discriminació i la violència.</li><li>Les xarxes amplifiquen els atacs i deixen les víctimes indefenses.</li><li>Les plataformes haurien de respondre pels continguts il·legals que no retiren.</li></ul></div></div><p>La Unió Europea ha aprovat la <b>Llei de serveis digitals</b>, que obliga les grans plataformes a retirar amb rapidesa contingut il·legal i a explicar com moderen.</p>")],
 [("Artículo", "Article", "20 de la Constitución", "20 de la Constitució"), ("Discurso de odio", "Discurs d'odi", "Art. 510 del Código Penal", "Art. 510 del Codi Penal")],
 ("El Consell de l'Audiovisual de Catalunya vigila los contenidos de radio y televisión en Catalunya, incluidos los discursos de odio.", "El Consell de l'Audiovisual de Catalunya vetlla pels continguts de ràdio i televisió a Catalunya, inclosos els discursos d'odi."),
 "Constitución Española (art. 20), Ley Orgánica 1/1982 de protección del honor, Código Penal (arts. 205 a 216 y 510) y Reglamento (UE) 2022/2065 de Servicios Digitales",
 [("datos", "Protección de datos", "Protecció de dades"), ("eticas", "Ética y derecho", "Ètica i dret")])

T_("animales", "eticas", ("etica/derechos-de-los-animales/", "ca/etica/drets-dels-animals/"), ("Debate · Animales", "Debat · Animals"),
 ("Los animales y la ley", "Els animals i la llei"),
 ("De cosas a «seres sintientes»: cómo ha cambiado la protección de los animales y qué se sigue discutiendo.", "De coses a «éssers sentents»: com ha canviat la protecció dels animals i què es continua discutint."),
 ("Desde 2022 el Código Civil dice que los animales son seres vivos dotados de sensibilidad, no simples cosas. Eso afecta a los divorcios (se decide con quién se queda la mascota), a los embargos y a las herencias. La ley de bienestar animal de 2023 prohíbe el sacrificio de animales de compañía salvo por motivos sanitarios y obliga a los dueños de perros a hacer un curso. Catalunya se adelantó: prohibió las corridas de toros en 2010.",
  "Des del 2022 el Codi Civil diu que els animals són éssers vius dotats de sensibilitat, no simples coses. Això afecta els divorcis (es decideix amb qui es queda la mascota), els embargaments i les herències. La llei de benestar animal del 2023 prohibeix el sacrifici d'animals de companyia excepte per motius sanitaris i obliga els propietaris de gossos a fer un curs. Catalunya s'hi va avançar: va prohibir les curses de braus el 2010."),
 [S("Qué obligaciones tienes con tu animal", "Quines obligacions tens amb el teu animal",
    "<ul><li>Identificarlo con microchip e inscribirlo en el registro (perros, gatos y hurones).</li><li>Darle cuidados, atención veterinaria y un lugar adecuado. No dejarlo solo más de 3 días (24 horas en el caso de los perros).</li><li>Los perros deben contar con un seguro de responsabilidad civil y sus dueños, con un curso de tenencia.</li><li>Abandonar o maltratar a un animal es infracción grave o delito (art. 340 bis del Código Penal), con penas de cárcel si causa la muerte.</li></ul>",
    "<ul><li>Identificar-lo amb microxip i inscriure'l al registre (gossos, gats i fures).</li><li>Donar-li cures, atenció veterinària i un lloc adequat. No deixar-lo sol més de 3 dies (24 hores en el cas dels gossos).</li><li>Els gossos han de tenir una assegurança de responsabilitat civil i els seus propietaris, un curs de tinença.</li><li>Abandonar o maltractar un animal és infracció greu o delicte (art. 340 bis del Codi Penal), amb penes de presó si en causa la mort.</li></ul>"),
  S("Mascotas en el divorcio y en el alquiler", "Mascotes en el divorci i en el lloguer",
    "<p>En una ruptura, el convenio regulador debe decir con quién vive el animal y cómo se reparten los gastos; el juez decide atendiendo a su bienestar, y puede acordar una custodia compartida. En el alquiler, el contrato puede prohibir tener animales: si quieres uno, pactarlo por escrito evita problemas. Si regalas o cedes un animal, deja constancia con un <a href=\"{canimal}\">documento de cesión</a>.</p>",
    "<p>En una ruptura, el conveni regulador ha de dir amb qui viu l'animal i com es reparteixen les despeses; el jutge decideix atenent el seu benestar, i pot acordar una custòdia compartida. En el lloguer, el contracte pot prohibir tenir animals: si en vols un, pactar-ho per escrit evita problemes. Si regales o cedeixes un animal, deixa'n constància amb un <a href=\"{canimal}\">document de cessió</a>.</p>"),
  S("El debate", "El debat",
    "<div class=\"pos\"><div><h3>Más protección</h3><ul><li>Si los animales sienten dolor, deberían tener derechos propios, no solo protección como bienes.</li><li>Los toros, la caza con perros o las granjas intensivas deberían limitarse.</li><li>La experimentación con animales debe sustituirse por métodos alternativos.</li></ul></div><div><h3>Más equilibrio</h3><ul><li>Solo las personas tienen derechos; los animales merecen trato digno, pero no son sujetos de derecho.</li><li>Las tradiciones rurales, la caza y la ganadería forman parte de la economía y la cultura.</li><li>Sin experimentación animal no habría muchas vacunas y medicamentos.</li></ul></div></div>",
    "<div class=\"pos\"><div><h3>Més protecció</h3><ul><li>Si els animals senten dolor, haurien de tenir drets propis, no només protecció com a béns.</li><li>Els braus, la caça amb gossos o les granges intensives s'haurien de limitar.</li><li>L'experimentació amb animals s'ha de substituir per mètodes alternatius.</li></ul></div><div><h3>Més equilibri</h3><ul><li>Només les persones tenen drets; els animals mereixen un tracte digne, però no són subjectes de dret.</li><li>Les tradicions rurals, la caça i la ramaderia formen part de l'economia i la cultura.</li><li>Sense experimentació animal no hi hauria moltes vacunes i medicaments.</li></ul></div></div>")],
 [("Seres sintientes", "Éssers sentents", "Desde 2022 (Ley 17/2021)", "Des del 2022 (Llei 17/2021)"), ("Ley de bienestar animal", "Llei de benestar animal", "Ley 7/2023", "Llei 7/2023")],
 ("Catalunya tiene su propia Ley de protección de los animales (Decret legislatiu 2/2008). El Parlament prohibió las corridas de toros en 2010; el Tribunal Constitucional anuló la prohibición en 2016, pero desde 2012 no se celebran en Catalunya.", "Catalunya té la seva pròpia Llei de protecció dels animals (Decret legislatiu 2/2008). El Parlament va prohibir les curses de braus el 2010; el Tribunal Constitucional va anul·lar la prohibició el 2016, però des del 2012 no se'n fan a Catalunya."),
 "Ley 17/2021 (régimen jurídico de los animales), Ley 7/2023 de protección de los derechos y el bienestar de los animales, Código Penal (art. 340 bis) y Decret legislatiu 2/2008",
 [("canimal", "Cesión de animal de compañía", "Cessió d'animal de companyia"), ("familia", "Familia", "Família")])

T_("gestacion", "eticas", ("etica/gestacion-subrogada/", "ca/etica/gestacio-subrogada/"), ("Debate · Familia", "Debat · Família"),
 ("Gestación subrogada", "Gestació subrogada"),
 ("Por qué en España no es válido el contrato de «vientre de alquiler», qué pasa con los bebés nacidos en el extranjero y qué argumentos se cruzan.", "Per què a Espanya no és vàlid el contracte de «ventre de lloguer», què passa amb els nadons nascuts a l'estranger i quins arguments es creuen."),
 ("En España el contrato por el que una mujer gesta un hijo para otras personas es nulo: la madre legal es siempre la que da a luz. Aun así, cientos de familias acuden cada año a países donde es legal. Desde 2023 los consulados no inscriben directamente a esos bebés; los padres deben pasar por un procedimiento judicial, normalmente de adopción o de reconocimiento de la filiación paterna biológica.",
  "A Espanya el contracte pel qual una dona gesta un fill per a altres persones és nul: la mare legal és sempre la que dona a llum. Tot i així, centenars de famílies van cada any a països on és legal. Des del 2023 els consolats no inscriuen directament aquests nadons; els pares han de passar per un procediment judicial, normalment d'adopció o de reconeixement de la filiació paterna biològica."),
 [S("Lo que dice la ley", "El que diu la llei",
    "<p>La Ley de técnicas de reproducción asistida declara nulo el contrato de gestación por sustitución, sea gratuito o pagado. La ley de 2023 sobre salud reproductiva la considera una forma de violencia contra las mujeres y prohíbe su publicidad. El Tribunal Supremo ha dicho que inscribir sin más a estos niños vulneraría los derechos de la madre gestante y del menor, pero que el interés del niño exige reconocer su relación con los padres por otras vías.</p>",
    "<p>La Llei de tècniques de reproducció assistida declara nul el contracte de gestació per substitució, sigui gratuït o pagat. La llei del 2023 sobre salut reproductiva la considera una forma de violència contra les dones i en prohibeix la publicitat. El Tribunal Suprem ha dit que inscriure sense més aquests infants vulneraria els drets de la mare gestant i del menor, però que l'interès de l'infant exigeix reconèixer-ne la relació amb els pares per altres vies.</p>"),
  S("En el mundo", "Al món",
    "<p>Está permitida en algunos estados de Estados Unidos, Canadá (solo altruista), Reino Unido (solo altruista), Grecia, Portugal (altruista y muy limitada), Georgia, México en algunos estados y otros países. La prohíben Francia, Alemania, Italia (que en 2024 la convirtió en «delito universal») y España. El Parlamento Europeo la ha condenado cuando hay explotación.</p>",
    "<p>Està permesa en alguns estats dels Estats Units, el Canadà (només altruista), el Regne Unit (només altruista), Grècia, Portugal (altruista i molt limitada), Geòrgia, Mèxic en alguns estats i altres països. La prohibeixen França, Alemanya, Itàlia (que el 2024 la va convertir en «delicte universal») i Espanya. El Parlament Europeu l'ha condemnada quan hi ha explotació.</p>"),
  S("Los argumentos", "Els arguments",
    "<div class=\"pos\"><div><h3>A favor de regularla</h3><ul><li>Permite tener hijos a personas que no pueden de otra forma.</li><li>Una regulación altruista, con garantías y control judicial, protegería mejor a todos que la prohibición.</li><li>Los niños ya nacidos necesitan seguridad jurídica.</li></ul></div><div><h3>En contra</h3><ul><li>Convierte el cuerpo de la mujer y al bebé en objeto de un contrato.</li><li>En la práctica se aprovecha de mujeres pobres de otros países.</li><li>Hay otras vías para formar una familia, como la adopción.</li></ul></div></div>",
    "<div class=\"pos\"><div><h3>A favor de regular-la</h3><ul><li>Permet tenir fills a persones que no en poden tenir d'una altra manera.</li><li>Una regulació altruista, amb garanties i control judicial, protegiria millor tothom que la prohibició.</li><li>Els infants ja nascuts necessiten seguretat jurídica.</li></ul></div><div><h3>En contra</h3><ul><li>Converteix el cos de la dona i el nadó en objecte d'un contracte.</li><li>A la pràctica s'aprofita de dones pobres d'altres països.</li><li>Hi ha altres vies per formar una família, com l'adopció.</li></ul></div></div>")],
 [("Contrato", "Contracte", "Nulo en España", "Nul a Espanya"), ("Norma", "Norma", "Ley 14/2006, art. 10", "Llei 14/2006, art. 10")],
 ("El derecho de filiación catalán también parte de que la madre es la que da a luz, aunque permite la doble maternidad por consentimiento a la reproducción asistida.", "El dret de filiació català també parteix que la mare és la que dona a llum, tot i que permet la doble maternitat per consentiment a la reproducció assistida."),
 "Ley 14/2006 sobre técnicas de reproducción humana asistida (art. 10), Ley Orgánica 1/2023 y sentencias del Tribunal Supremo de 2022 y 2024",
 [("familia", "Familia", "Família"), ("aborto", "El aborto: la ley y el debate", "L'avortament: la llei i el debat")])

# ============================ MORAL ============================
T_("mujer", "moral", ("moral/igualdad-de-la-mujer/", "ca/moral/igualtat-de-la-dona/"), ("Derechos · Igualdad", "Drets · Igualtat"),
 ("La mujer en la ley: de la licencia marital a la paridad", "La dona a la llei: de la llicència marital a la paritat"),
 ("Hace menos de cincuenta años una mujer casada no podía abrir una cuenta sin permiso de su marido. Así ha cambiado la ley.", "Fa menys de cinquanta anys una dona casada no podia obrir un compte sense permís del seu marit. Així ha canviat la llei."),
 ("Durante buena parte del siglo XX la ley española trataba a la mujer casada como dependiente de su marido: necesitaba su licencia para trabajar, firmar contratos o abrir una cuenta. La República reconoció el voto y el divorcio en 1931-1932, el franquismo los suprimió y la democracia trajo la igualdad plena ante la ley. Hoy el debate está en la igualdad real: brecha salarial, cuidados y violencia de género.",
  "Durant bona part del segle XX la llei espanyola tractava la dona casada com a dependent del marit: necessitava la seva llicència per treballar, signar contractes o obrir un compte. La República va reconèixer el vot i el divorci el 1931-1932, el franquisme els va suprimir i la democràcia va portar la igualtat plena davant la llei. Avui el debat és en la igualtat real: bretxa salarial, cures i violència de gènere."),
 [S("Cronología", "Cronologia",
    "<ul><li><b>1931</b>: la Constitución republicana reconoce el voto femenino, defendido por Clara Campoamor.</li><li><b>1938-1975</b>: el franquismo restablece el Código Civil de 1889: la mujer casada debe obediencia al marido y necesita su <b>licencia marital</b>.</li><li><b>1961</b>: ley de derechos políticos, profesionales y laborales de la mujer, impulsada por Mercedes Formica y la Sección Femenina; sigue la licencia para casadas.</li><li><b>1975</b>: se suprime la licencia marital.</li><li><b>1978</b>: la Constitución prohíbe toda discriminación por razón de sexo; se despenalizan el adulterio y los anticonceptivos.</li><li><b>1981</b>: patria potestad compartida y divorcio.</li><li><b>2004</b>: ley integral contra la violencia de género.</li><li><b>2007</b>: ley de igualdad efectiva, con planes de igualdad en empresas y listas electorales equilibradas.</li><li><b>2024</b>: ley de paridad en órganos de decisión.</li></ul>",
    "<ul><li><b>1931</b>: la Constitució republicana reconeix el vot femení, defensat per Clara Campoamor.</li><li><b>1938-1975</b>: el franquisme restableix el Codi Civil del 1889: la dona casada deu obediència al marit i necessita la seva <b>llicència marital</b>.</li><li><b>1961</b>: llei de drets polítics, professionals i laborals de la dona, impulsada per Mercedes Formica i la Secció Femenina; continua la llicència per a les casades.</li><li><b>1975</b>: se suprimeix la llicència marital.</li><li><b>1978</b>: la Constitució prohibeix tota discriminació per raó de sexe; es despenalitzen l'adulteri i els anticonceptius.</li><li><b>1981</b>: pàtria potestat compartida i divorci.</li><li><b>2004</b>: llei integral contra la violència de gènere.</li><li><b>2007</b>: llei d'igualtat efectiva, amb plans d'igualtat a les empreses i llistes electorals equilibrades.</li><li><b>2024</b>: llei de paritat en òrgans de decisió.</li></ul>"),
  S("Lo que dice hoy la ley", "El que diu avui la llei",
    "<ul><li>Igual salario por trabajo de igual valor; las empresas deben llevar un <b>registro salarial</b> y, desde 50 trabajadores, un plan de igualdad.</li><li>Permiso por nacimiento igual e intransferible para cada progenitor.</li><li>Las listas electorales y los consejos de administración de grandes empresas deben tener entre un 40 % y un 60 % de cada sexo.</li><li>Medidas de protección específicas frente a la violencia de género, con juzgados especializados.</li></ul>",
    "<ul><li>Igual salari per feina d'igual valor; les empreses han de portar un <b>registre salarial</b> i, des de 50 treballadors, un pla d'igualtat.</li><li>Permís per naixement igual i intransferible per a cada progenitor.</li><li>Les llistes electorals i els consells d'administració de grans empreses han de tenir entre un 40 % i un 60 % de cada sexe.</li><li>Mesures de protecció específiques davant la violència de gènere, amb jutjats especialitzats.</li></ul>"),
  S("El debate actual", "El debat actual",
    "<p>Hoy hay consenso sobre la igualdad ante la ley, pero se discute cómo lograr la igualdad real. Unos defienden cuotas, permisos más largos y medidas de acción positiva; otros creen que las cuotas vulneran el mérito o que la ley no debe distinguir por sexo ni siquiera para favorecer. También se debate el alcance de la ley del «solo sí es sí» de 2022 y su reforma de 2023.</p>",
    "<p>Avui hi ha consens sobre la igualtat davant la llei, però es discuteix com aconseguir la igualtat real. Uns defensen quotes, permisos més llargs i mesures d'acció positiva; d'altres creuen que les quotes vulneren el mèrit o que la llei no ha de distingir per sexe ni tan sols per afavorir. També es debat l'abast de la llei del «només sí és sí» del 2022 i la seva reforma del 2023.</p>")],
 [("Voto femenino", "Vot femení", "1931", "1931"), ("Fin de la licencia marital", "Fi de la llicència marital", "1975", "1975"), ("Ley de igualdad", "Llei d'igualtat", "Ley Orgánica 3/2007", "Llei Orgànica 3/2007")],
 ("Catalunya tiene su propia Llei 17/2015 d'igualtat efectiva de dones i homes y la Llei 5/2008 del dret de les dones a erradicar la violència masclista.", "Catalunya té la seva pròpia Llei 17/2015 d'igualtat efectiva de dones i homes i la Llei 5/2008 del dret de les dones a erradicar la violència masclista."),
 "Constitución Española (art. 14), Ley 14/1975, Ley Orgánica 3/2007 y Ley Orgánica 2/2024 de representación paritaria",
 [("bio", "Clara Campoamor", "Clara Campoamor"), ("divorcio", "El divorcio en España", "El divorci a Espanya")])

T_("religion", "moral", ("moral/religion-y-estado/", "ca/moral/religio-i-estat/"), ("Sociedad · Religión", "Societat · Religió"),
 ("Religión y Estado en España", "Religió i Estat a Espanya"),
 ("De la religión oficial a un Estado aconfesional: matrimonio, educación, impuestos y libertad religiosa.", "De la religió oficial a un Estat aconfessional: matrimoni, educació, impostos i llibertat religiosa."),
 ("Durante siglos el catolicismo fue la religión oficial y obligatoria en España. La Constitución de 1978 declara que «ninguna confesión tendrá carácter estatal», pero obliga a los poderes públicos a cooperar con la Iglesia católica y las demás confesiones. Por eso hay clase de religión optativa, casilla en la declaración de la renta y acuerdos con judíos, musulmanes y evangélicos.",
  "Durant segles el catolicisme va ser la religió oficial i obligatòria a Espanya. La Constitució del 1978 declara que «cap confessió no tindrà caràcter estatal», però obliga els poders públics a cooperar amb l'Església catòlica i les altres confessions. Per això hi ha classe de religió optativa, casella a la declaració de la renda i acords amb jueus, musulmans i evangèlics."),
 [S("Una historia de idas y venidas", "Una història d'anades i vingudes",
    "<ul><li><b>1492 y 1609</b>: expulsión de judíos y moriscos; la Inquisición vigila la ortodoxia hasta 1834.</li><li><b>1812</b>: la Constitución de Cádiz declara la religión católica «única verdadera» y prohíbe las demás.</li><li><b>1869</b>: primera libertad de cultos.</li><li><b>1931</b>: la República separa Iglesia y Estado, aprueba el matrimonio civil y el divorcio y disuelve a los jesuitas.</li><li><b>1939-1975</b>: nacionalcatolicismo; Concordato de 1953.</li><li><b>1967</b>: ley de libertad religiosa limitada.</li><li><b>1978-1980</b>: Constitución aconfesional, Acuerdos con la Santa Sede (1979) y Ley Orgánica de Libertad Religiosa (1980).</li></ul>",
    "<ul><li><b>1492 i 1609</b>: expulsió de jueus i moriscos; la Inquisició vigila l'ortodòxia fins al 1834.</li><li><b>1812</b>: la Constitució de Cadis declara la religió catòlica «única verdadera» i prohibeix les altres.</li><li><b>1869</b>: primera llibertat de cultes.</li><li><b>1931</b>: la República separa Església i Estat, aprova el matrimoni civil i el divorci i dissol els jesuïtes.</li><li><b>1939-1975</b>: nacionalcatolicisme; Concordat del 1953.</li><li><b>1967</b>: llei de llibertat religiosa limitada.</li><li><b>1978-1980</b>: Constitució aconfessional, Acords amb la Santa Seu (1979) i Llei Orgànica de Llibertat Religiosa (1980).</li></ul>"),
  S("Cómo funciona hoy", "Com funciona avui",
    "<ul><li><b>Matrimonio religioso</b>: la boda católica, judía, musulmana, evangélica y de otras confesiones con acuerdo tiene efectos civiles si se inscribe en el Registro Civil.</li><li><b>Educación</b>: la clase de religión es de oferta obligatoria para los centros y voluntaria para los alumnos, y no cuenta para la nota media en bachillerato.</li><li><b>Impuestos</b>: puedes destinar el 0,7 % de tu IRPF a la Iglesia católica, a fines sociales, a las dos casillas o a ninguna; no pagas más por ello.</li><li><b>Libertad religiosa</b>: incluye no tener religión, cambiar de creencias y no declarar sobre ellas.</li></ul>",
    "<ul><li><b>Matrimoni religiós</b>: el casament catòlic, jueu, musulmà, evangèlic i d'altres confessions amb acord té efectes civils si s'inscriu al Registre Civil.</li><li><b>Educació</b>: la classe de religió és d'oferta obligatòria per als centres i voluntària per als alumnes, i no compta per a la nota mitjana al batxillerat.</li><li><b>Impostos</b>: pots destinar el 0,7 % del teu IRPF a l'Església catòlica, a finalitats socials, a les dues caselles o a cap; no pagues més per això.</li><li><b>Llibertat religiosa</b>: inclou no tenir religió, canviar de creences i no declarar-ne.</li></ul>"),
  S("Lo que se debate", "El que es debat",
    "<p>Hay quien pide revisar los Acuerdos de 1979 por considerarlos un privilegio y avanzar hacia un Estado laico, y quien defiende que la cooperación refleja el peso social y cultural del catolicismo. Otros temas recurrentes: los símbolos religiosos en espacios públicos, las inmatriculaciones de bienes por la Iglesia (el Gobierno publicó en 2021 un listado de casi 35.000), el velo islámico en escuelas y trabajos, y el delito de escarnio de los sentimientos religiosos.</p>",
    "<p>Hi ha qui demana revisar els Acords del 1979 perquè els considera un privilegi i avançar cap a un Estat laic, i qui defensa que la cooperació reflecteix el pes social i cultural del catolicisme. Altres temes recurrents: els símbols religiosos en espais públics, les immatriculacions de béns per l'Església (el Govern va publicar el 2021 una llista de gairebé 35.000), el vel islàmic a escoles i feines, i el delicte d'escarni dels sentiments religiosos.</p>")],
 [("Estado", "Estat", "Aconfesional (art. 16 CE)", "Aconfessional (art. 16 CE)"), ("Casilla de la renta", "Casella de la renda", "0,7 %", "0,7 %")],
 ("La Generalitat tiene una Direcció General d'Afers Religiosos y una ley propia sobre centros de culto (Llei 16/2009), que regula las licencias municipales para abrir lugares de culto.", "La Generalitat té una Direcció General d'Afers Religiosos i una llei pròpia sobre centres de culte (Llei 16/2009), que regula les llicències municipals per obrir llocs de culte."),
 "Constitución Española (art. 16), Ley Orgánica 7/1980 de Libertad Religiosa, Acuerdos con la Santa Sede de 1979 y leyes 24, 25 y 26/1992",
 [("matrimonio", "Matrimonio entre personas del mismo sexo", "Matrimoni entre persones del mateix sexe"), ("historia", "Historia del derecho", "Història del dret")])

T_("drogas", "moral", ("moral/drogas-tabaco-y-alcohol/", "ca/moral/drogues-tabac-i-alcohol/"), ("Sociedad · Salud", "Societat · Salut"),
 ("Drogas, tabaco y alcohol: cómo ha cambiado la ley", "Drogues, tabac i alcohol: com ha canviat la llei"),
 ("De fumar en los aviones a los espacios sin humo; del cannabis en clubes a lo que dice hoy el Código Penal.", "De fumar als avions als espais sense fum; del cànnabis en clubs al que diu avui el Codi Penal."),
 ("En España consumir drogas no es delito, pero hacerlo en la vía pública es una infracción administrativa con multas desde 601 €. Vender, cultivar para terceros o tener cantidades que indiquen tráfico sí es delito. El tabaco está prohibido en bares y restaurantes desde 2011, y el alcohol no se puede vender a menores de 18 años. La moral social sobre estas sustancias ha cambiado mucho en pocas décadas.",
  "A Espanya consumir drogues no és delicte, però fer-ho a la via pública és una infracció administrativa amb multes des de 601 €. Vendre, cultivar per a tercers o tenir quantitats que indiquin tràfic sí que és delicte. El tabac està prohibit a bars i restaurants des del 2011, i l'alcohol no es pot vendre a menors de 18 anys. La moral social sobre aquestes substàncies ha canviat molt en poques dècades."),
 [S("Lo que dice la ley", "El que diu la llei",
    "<ul><li><b>Consumo privado</b>: no es delito ni infracción.</li><li><b>Consumo o tenencia en la vía pública</b>: infracción grave de la Ley de Seguridad Ciudadana, de 601 a 30.000 €. Se puede sustituir por un programa de deshabituación si eres menor.</li><li><b>Tráfico</b>: vender, regalar o facilitar drogas es delito, con penas de 3 a 6 años de cárcel para las «duras» y de 1 a 3 años para el cannabis, más multa.</li><li><b>Conducir</b> con presencia de drogas en el organismo es infracción grave (multa de 1.000 € y 6 puntos); bajo su influencia, delito.</li></ul>",
    "<ul><li><b>Consum privat</b>: no és delicte ni infracció.</li><li><b>Consum o tinença a la via pública</b>: infracció greu de la Llei de seguretat ciutadana, de 601 a 30.000 €. Es pot substituir per un programa de deshabituació si ets menor.</li><li><b>Tràfic</b>: vendre, regalar o facilitar drogues és delicte, amb penes de 3 a 6 anys de presó per a les «dures» i d'1 a 3 anys per al cànnabis, més multa.</li><li><b>Conduir</b> amb presència de drogues a l'organisme és infracció greu (multa de 1.000 € i 6 punts); sota la seva influència, delicte.</li></ul>"),
  S("El tabaco y el alcohol", "El tabac i l'alcohol",
    "<p>En los años ochenta se fumaba en hospitales, aulas y aviones. La <b>ley de 2005</b> prohibió fumar en el trabajo y la de <b>2010</b>, en todos los bares y restaurantes, con amplio cumplimiento. Hoy se discute ampliar los espacios sin humo a terrazas y regular los vapeadores. El alcohol no se puede vender a menores de 18 años y cada comunidad regula los horarios de venta; en 2025 se tramitó una ley estatal para prevenir el consumo de alcohol en menores.</p>",
    "<p>Als anys vuitanta es fumava en hospitals, aules i avions. La <b>llei del 2005</b> va prohibir fumar a la feina i la del <b>2010</b>, a tots els bars i restaurants, amb un ampli compliment. Avui es discuteix ampliar els espais sense fum a les terrasses i regular els vapejadors. L'alcohol no es pot vendre a menors de 18 anys i cada comunitat regula els horaris de venda; el 2025 es va tramitar una llei estatal per prevenir el consum d'alcohol en menors.</p>"),
  S("El debate sobre el cannabis", "El debat sobre el cànnabis",
    "<div class=\"pos\"><div><h3>Por regularlo</h3><ul><li>La prohibición alimenta el mercado negro y no reduce el consumo.</li><li>Una venta regulada permitiría controlar la calidad y cobrar impuestos.</li><li>Países como Uruguay, Canadá, Alemania o Malta ya lo han regulado.</li><li>El cannabis medicinal ya se ha aprobado en España para usos concretos.</li></ul></div><div><h3>Por mantener la prohibición</h3><ul><li>El cannabis tiene riesgos para la salud mental, sobre todo en jóvenes.</li><li>Legalizarlo normaliza el consumo y lo aumenta.</li><li>Los efectos de la regulación en otros países aún no están claros.</li></ul></div></div>",
    "<div class=\"pos\"><div><h3>Per regular-lo</h3><ul><li>La prohibició alimenta el mercat negre i no redueix el consum.</li><li>Una venda regulada permetria controlar la qualitat i cobrar impostos.</li><li>Països com l'Uruguai, el Canadà, Alemanya o Malta ja l'han regulat.</li><li>El cànnabis medicinal ja s'ha aprovat a Espanya per a usos concrets.</li></ul></div><div><h3>Per mantenir la prohibició</h3><ul><li>El cànnabis té riscos per a la salut mental, sobretot en joves.</li><li>Legalitzar-lo normalitza el consum i l'augmenta.</li><li>Els efectes de la regulació en altres països encara no són clars.</li></ul></div></div>")],
 [("Multa por consumo en la calle", "Multa per consum al carrer", "Desde 601 €", "Des de 601 €"), ("Tabaco en bares", "Tabac als bars", "Prohibido desde 2011", "Prohibit des del 2011")],
 ("El Parlament aprobó en 2017 una ley que regulaba los clubes de cannabis, pero el Tribunal Constitucional la anuló en 2018 porque el derecho penal es competencia del Estado. Los clubes siguen existiendo en una zona gris, apoyados en el consumo compartido entre adultos.", "El Parlament va aprovar el 2017 una llei que regulava els clubs de cànnabis, però el Tribunal Constitucional la va anul·lar el 2018 perquè el dret penal és competència de l'Estat. Els clubs continuen existint en una zona grisa, recolzats en el consum compartit entre adults."),
 "Código Penal (arts. 368 a 378), Ley Orgánica 4/2015 de Seguridad Ciudadana, Ley 28/2005 de medidas frente al tabaquismo y STC 100/2018",
 [("administracion", "Administración: multas y recursos", "Administració: multes i recursos"), ("moral", "La moral y su evolución", "La moral i la seva evolució")])

T_("mili", "moral", ("moral/servicio-militar-y-objecion/", "ca/moral/servei-militar-i-objeccio/"), ("Sociedad · Defensa", "Societat · Defensa"),
 ("El servicio militar y la objeción de conciencia", "El servei militar i l'objecció de consciència"),
 ("La «mili» fue obligatoria para los hombres durante casi dos siglos. Así se llegó a su fin en 2001.", "La «mili» va ser obligatòria per als homes durant gairebé dos segles. Així es va arribar a la seva fi el 2001."),
 ("Durante generaciones, todos los varones españoles debían hacer el servicio militar. La Constitución de 1978 reconoció la objeción de conciencia, y en los años noventa miles de jóvenes se negaron a hacer tanto la mili como la prestación social sustitutoria (los «insumisos»), lo que llevó a cientos a prisión. En 2001 el servicio militar obligatorio se suspendió y las Fuerzas Armadas pasaron a ser profesionales.",
  "Durant generacions, tots els homes espanyols havien de fer el servei militar. La Constitució del 1978 va reconèixer l'objecció de consciència, i als anys noranta milers de joves es van negar a fer tant la mili com la prestació social substitutòria (els «insubmisos»), cosa que en va portar centenars a la presó. El 2001 el servei militar obligatori es va suspendre i les Forces Armades van passar a ser professionals."),
 [S("De las quintas a la mili", "De les quintes a la mili",
    "<p>En el siglo XIX se reclutaba por sorteo («quintas») y los ricos podían librarse pagando la «redención en metálico» o un sustituto, lo que provocó revueltas populares. Desde 1912 el servicio fue universal para los varones, aunque se podía reducir pagando como «soldado de cuota». Durante el franquismo y la democracia duraba entre 24 y 9 meses, y llegó a ser un rito de paso para los jóvenes.</p>",
    "<p>Al segle XIX es reclutava per sorteig («quintes») i els rics se'n podien lliurar pagant la «redempció en metàl·lic» o un substitut, cosa que va provocar revoltes populars. Des del 1912 el servei va ser universal per als homes, tot i que es podia reduir pagant com a «soldat de quota». Durant el franquisme i la democràcia durava entre 24 i 9 mesos, i va arribar a ser un ritu de pas per als joves.</p>"),
  S("Objetores e insumisos", "Objectors i insubmisos",
    "<ul><li><b>1971</b>: Pepe Beunza es el primer objetor por motivos no religiosos y es encarcelado.</li><li><b>1978</b>: la Constitución reconoce la objeción de conciencia (art. 30).</li><li><b>1984</b>: ley de objeción y prestación social sustitutoria, más larga que la mili.</li><li><b>1989-2001</b>: movimiento de insumisión: unos 50.000 jóvenes rechazan también la prestación sustitutoria; cerca de mil son condenados a prisión o inhabilitación.</li><li><b>2001</b>: se suspende el servicio militar obligatorio y se indulta a los insumisos.</li></ul>",
    "<ul><li><b>1971</b>: Pepe Beunza és el primer objector per motius no religiosos i és empresonat.</li><li><b>1978</b>: la Constitució reconeix l'objecció de consciència (art. 30).</li><li><b>1984</b>: llei d'objecció i prestació social substitutòria, més llarga que la mili.</li><li><b>1989-2001</b>: moviment d'insubmissió: uns 50.000 joves rebutgen també la prestació substitutòria; prop de mil són condemnats a presó o inhabilitació.</li><li><b>2001</b>: se suspèn el servei militar obligatori i s'indulta els insubmisos.</li></ul>"),
  S("¿Volverá la mili?", "Tornarà la mili?",
    "<p>El servicio militar no está abolido, solo <b>suspendido</b>: la Constitución sigue diciendo que los españoles tienen el derecho y el deber de defender a España, y una ley podría reactivarlo en caso de crisis. Tras la invasión de Ucrania, países como Suecia, Letonia o Lituania han recuperado formas de servicio obligatorio, y en Europa ha vuelto el debate. En España, por ahora, ningún gran partido propone recuperarlo.</p>",
    "<p>El servei militar no està abolit, només <b>suspès</b>: la Constitució continua dient que els espanyols tenen el dret i el deure de defensar Espanya, i una llei el podria reactivar en cas de crisi. Després de la invasió d'Ucraïna, països com Suècia, Letònia o Lituània han recuperat formes de servei obligatori, i a Europa ha tornat el debat. A Espanya, de moment, cap gran partit proposa recuperar-lo.</p>")],
 [("Fin de la mili obligatoria", "Fi de la mili obligatòria", "31 de diciembre de 2001", "31 de desembre del 2001"), ("Objeción en la Constitución", "Objecció a la Constitució", "Art. 30", "Art. 30")],
 ("Catalunya fue uno de los focos del movimiento objetor e insumiso, con colectivos como el MOC (Moviment d'Objecció de Consciència).", "Catalunya va ser un dels focus del moviment objector i insubmís, amb col·lectius com el MOC (Moviment d'Objecció de Consciència)."),
 "Constitución Española (art. 30), Ley 48/1984 de objeción de conciencia y Real Decreto 247/2001",
 [("historia", "Historia del derecho", "Història del dret"), ("moral", "La moral y su evolución", "La moral i la seva evolució")])

# ======================= RENDER =======================
HUBLBL = {"catalunya": ("Más sobre Catalunya", "Més sobre Catalunya"), "internacional": ("Más fichas de la UE", "Més fitxes de la UE"),
          "eticas": ("Más debates", "Més debats"), "moral": ("Más temas", "Més temes")}

def tema_page(d, lang):
    es = lang == "es"; i = 0 if es else 1
    t = lambda a, b: a if es else b
    toc = "".join(f'<li><a href="#{_slug(s[i])}">{s[i]}</a></li>' for s in d["secs"])
    body = (f'<div class="claro"><span class="label">{t("En 30 segundos", "En 30 segons")}</span><p>{d["resumen"][i]}</p></div>'
            + (f'<nav class="toc"><span class="label">{t("En esta página", "En aquesta pàgina")}</span><ol>{toc}</ol></nav>' if len(d["secs"]) > 3 else "")
            + "".join(f'<h2 id="{_slug(s[i])}">{s[i]}</h2>{s[2 + i]}' for s in d["secs"])
            + vig(lang, d["fuente"]))
    dl = "".join(f'<dt>{x[0 + i]}</dt><dd>{x[2 + i]}</dd>' for x in d["datos"])
    side = (box(t("Datos clave", "Dades clau"), f'<dl>{dl}</dl>')
            + box(t("En Catalunya", "A Catalunya") if d["hub"] != "catalunya" else t("Sabías que", "Sabies que"), f'<p>{d["nota"][i]}</p>', "box cc")
            + box(t("Te puede servir", "Et pot servir"), ul([f'<a href="{{{k}}}">{a if es else b}</a>' for k, a, b in d["rel"]])))
    return ficha(d["label"][i], d["nom"][i], d["lead"][i], [], body, side)

for d in TEMAS:
    ROUTES[d["key"]] = d["rutas"]
    PARENT[d["key"]] = d["hub"]
for d in TEMAS:
    PAGES[d["key"]] = {L: dict(title=d["nom"][0 if L == "es" else 1], desc=d["lead"][0 if L == "es" else 1],
                                crumbs=[(d["hub"], PAGES[d["hub"]][L]["title"].split(":")[0])], html=tema_page(d, L)) for L in ("es", "ca")}

# Tarjetas en cada sección
for hub, (le, lc) in HUBLBL.items():
    for L in ("es", "ca"):
        es = L == "es"
        cards = "".join(f'<a class="card" href="{{{d["key"]}}}"><span class="label">{d["label"][0 if es else 1]}</span><h3>{d["nom"][0 if es else 1]}</h3><p>{d["lead"][0 if es else 1]}</p><span class="go">{"Leer la ficha" if es else "Llegir la fitxa"}</span></a>' for d in TEMAS if d["hub"] == hub)
        blk = f'<div class="wrap temas"><h2 class="sec">{le if es else lc}</h2><div class="cols">{cards}</div></div>'
        if hub == "catalunya":
            carga = "Se cargan cada día de la fuente oficial." if es else "Es carreguen cada dia de la font oficial."
            dogc = (f'<div class="dogcbox"><h2 class="sec">{"Últimas normas publicadas en el DOGC" if es else "Darreres normes publicades al DOGC"}</h2>'
                    f'<p class="status" id="dogc-cat">{carga}</p><ul class="dispo" data-feed="dogc" data-info="dogc-cat"></ul>'
                    f'<p><a href="{{novedades}}">{"Ver también el BOE y el Diario Oficial de la UE" if es else "Veure també el BOE i el Diari Oficial de la UE"}</a></p></div>')
            hh = PAGES[hub][L]["html"]
            card = (f'<aside class="panel diarios dogc-top"><a class="diario" href="#dogc-lista"><span class="sig cat">DOGC</span><span class="dt"><b id="dogc-n">{"Últimas normas del DOGC" if es else "Darreres normes del DOGC"}</b>'
                    f'<span id="dogc-fecha">Diari Oficial de la Generalitat de Catalunya</span></span><span class="go">›</span></a>'
                    f'<a class="diario" href="https://dogc.gencat.cat/{"es" if es else "ca"}/" target="_blank" rel="noopener"><span class="sig cat">DOGC</span><span class="dt"><b>{"Web oficial del DOGC" if es else "Web oficial del DOGC"}</b><span>dogc.gencat.cat</span></span><span class="go">↗</span></a></aside>')
            f0 = hh.find('<div class="fhead">')
            f1 = hh.find('</div>', f0) + 6 if f0 >= 0 else -1
            if f1 > 5:
                hh = hh[:f1] + card + hh[f1:]
            dogc = dogc.replace('<div class="dogcbox">', '<div class="dogcbox" id="dogc-lista">')
            k = hh.find("</table></div>")
            PAGES[hub][L]["html"] = hh[:k + 14] + dogc + hh[k + 14:] if k >= 0 else dogc + hh
        PAGES[hub][L]["html"] = PAGES[hub][L]["html"] + blk

# Títulos de la portada que llevan a su sección
for L, pares in (("es", [("Materias", "materias"), ("Contratos gratis para el día a día", "contratos"), ("La historia del derecho en España y Catalunya", "historia"), ("Guías prácticas", "materias")]),
                 ("ca", [("Matèries", "materias"), ("Contractes gratuïts per al dia a dia", "contratos"), ("La història del dret a Espanya i Catalunya", "historia"), ("Guies pràctiques", "materias")])):
    for txt, k in pares:
        PAGES["home"][L]["html"] = PAGES["home"][L]["html"].replace(f"<h2>{txt}</h2>", f'<h2><a class="h2link" href="{{{k}}}">{txt} <span aria-hidden="true">›</span></a></h2>', 1)
